// P1 Theme I · End of the Cold War (Topic 3) — from Cold_War_Study_Notes_Theme1 (Sections 15–22, 23.1, 23.4)
(function(){
const S = "Cold War study notes";
const add = (sec, o) => CASES.push(Object.assign({ t:"cw3", sec, src:S, qs:"me" }, o));

/* ── 15. Syllabus Map & Essential Question — Topic 3 ── */
add("Syllabus Map & Essential Question — Topic 3", { id:"cw3-syllabus", exp:"The four sub-topics map onto the three candidate ‘agents’ of the end of the Cold War: the USA (renewed containment, arms control, SDI, Reagan Doctrine), the USSR (economic decline, New Thinking, Sinatra Doctrine) and the people of Eastern Europe (Poland, East Germany). Sub-topic 4 then asks you to weigh them against each other through the triumphalist, Soviet initiative and People Power debates, so every piece of content you learn should be tagged to one of these schools.", title:"Topic 3 syllabus sub-topics", when:"framework",
  q:"What are the four sub-topics of Topic 3 (source-based case study) and the Essential Question?",
  pts:["Essential Question: How did the Cold War develop? How did the Cold War impact global developments after 1945?",
       "1. The USA's policy of renewed confrontation and containment: USA's role in arms control negotiations, Strategic Defense Initiative programme, Reagan Doctrine",
       "2. Decline of the USSR and shifts in Soviet foreign policy: economic problems, Gorbachev's ‘New Thinking’, Sinatra Doctrine",
       "3. Eastern European movements and revolutions in the 1980s: Poland and East Germany",
       "4. Historical interpretations of the end of the Cold War: Western triumphalist, Soviet initiative and ‘People Power’ debates",
       "Questions set will not require candidates to compare the Korean War, the Vietnam War and the Cuban Missile Crisis (Topic 2 case studies)",
       "Compiled from T3W3-4, T3W5-6, T3W7-8 and T3W9 lectures"] });
add("Syllabus Map & Essential Question — Topic 3", { id:"cw3-guiding", exp:"The guiding questions move from definition (what and when was the end?) to causes (Reagan, Soviet decline, Eastern European movements) and finally to judgement (who or what was responsible?). Answering the first question well matters, because how you define and date the end of the Cold War shapes which actor looks most important; treating it as a 1980s process rather than one event allows a balanced, multi-causal answer.", title:"Guiding questions across the four lectures", when:"framework",
  q:"What are the guiding questions across the four Topic 3 lectures?", qs:"notes",
  pts:["What is the end of the Cold War? When did it end? What do ‘renewed containment and confrontation’ mean, and how are they linked to earlier phases?",
       "What were the reasons for, features and impact of Reagan's revived containment?",
       "What does the decline of the USSR mean — what exactly declined, when did it start, and what were its causes?",
       "What were the key Eastern European movements/revolutions of the 1980s, and how did they lead to the end of the Cold War?",
       "What were the different historical interpretations of who/what ended the Cold War?"] });
add("Syllabus Map & Essential Question — Topic 3", { id:"cw3-end-vs-collapse", exp:"This distinction is the anchor for all of Topic 3. The Cold War ended when superpower tensions relaxed and the division of Europe disappeared (1989, Malta), while the USSR’s break-up in 1991 was a separate outcome that the end of the Cold War did not require. Confusing the two lets you wrongly argue that whoever ‘destroyed’ the USSR ended the Cold War; keeping them apart lets you argue that the collapse was largely a consequence, not a cause.", title:"End of the Cold War vs. collapse of the USSR", when:"1989 vs Dec 1991",
  q:"Distinguish the end of the Cold War from the collapse of the Soviet Union (date, nature, relationship).",
  pts:["End of the Cold War: 1989 — a process through the 1980s, culminating in the Malta Declaration, Dec 1989",
       "Collapse of the USSR: Dec 1991 — USSR dissolves into 15 independent republics",
       "Nature (end of CW): mutual relaxation of tensions between the two superpowers; end of division of Europe/bloc alliances",
       "Nature (collapse): end of the USSR as a unified state, of CPSU rule, and of Gorbachev's leadership",
       "Not synonymous — the end of the Cold War did NOT require the USSR to break up",
       "Collapse was largely a product/outcome of the end of the Cold War, not its cause; analogous/parallel process, not the same event"] });

/* ── 16. US Renewed Containment and Confrontation (1981–85) ── */
add("16.1 Understanding the Terms", { id:"cw3-end-def", exp:"Defining the end as a process rather than a single event matters because it lets landmark moments like the Wall’s fall and the USSR’s collapse sit inside a longer development of the 1980s. The definition also builds in both top-down (Reagan–Gorbachev convergence) and bottom-up (the people) drivers, which signals that a good answer should combine leadership and popular pressure rather than credit just one.", title:"Defining ‘end of the Cold War’", when:"1980s",
  q:"How do the notes define ‘the end of the Cold War’?",
  pts:["Developments/interactions between the West and Soviet blocs during the 1980s culminating in mutual relaxation of tensions",
       "A process, not a single event",
       "Encompasses landmark moments: fall of the Berlin Wall (Nov 1989); announced collapse of the USSR (Dec 1991)",
       "A combination of top-down change (Reagan–Gorbachev convergence) and bottom-up pressure (the people)"] });
add("16.1 Understanding the Terms", { id:"renewedcontainment", exp:"‘Renewed’ containment is defined by contrast: it was more aggressive than the détente before 1980 and the new détente after 1985. Placing 1979–85 as the ‘2nd Cold War’ within the wider periodisation shows that US–Soviet relations moved in cycles of tension and relaxation, so Reagan’s first term can be framed as a return to confrontation rather than something wholly new, which helps when judging how distinctive his policy really was.", title:"Renewed containment and confrontation", when:"1979–85",
  q:"What is meant by ‘renewed containment and confrontation’, and where does it sit in the periodisation of US–Soviet relations?",
  clue:"US policy carried out more aggressively from the early 1980s, contrasted with the relaxation before 1980 and the “new détente” after 1985.",
  pts:["US containment carried out more aggressively from the early 1980s, with features not significantly visible before 1980",
       "Viewed in contrast to détente before 1980 and the “new détente” after 1985",
       "Periodisation: 1945–55 Cold War I; 1955–58 Peaceful Coexistence; 1958–62 Cold War I (re-emergence)",
       "1963–79 Détente; 1979–85 2nd Cold War; 1985–91 New Détente"] });
add("16.1 Understanding the Terms", { id:"cw3-lundestad-rv", exp:"Lundestad captures what makes the Reagan Victory School distinctive: it claims Reagan broke with status-quo containment and actively sought Western ‘victory’ and Soviet collapse. This is the thesis you will later test against evidence; if Reagan really aimed to win rather than coexist, then the end of the Cold War looks like an American achievement, but the school’s limitations (Section 16.5) challenge that causal link.", title:"Lundestad on the Reagan Victory School", when:"2003",
  q:"How does Lundestad (2003) characterise the Reagan Victory/Western Triumphalist School?",
  pts:["These writers see Ronald Reagan as different from his predecessors",
       "He gave up the containment policy based on the status quo",
       "Instead tried to bring about the ‘victory’ of the West and the collapse of the ‘evil empire’"] });
add("16.1 Understanding the Terms", { id:"cw3-players", exp:"Knowing who held power in each phase lets you link policy shifts to personalities. The 2nd Cold War saw three ageing Soviet leaders in quick succession facing Carter and then Reagan, whereas the new détente coincided with Gorbachev’s arrival. That overlap is why historians argue over whether the 1985 turning point came from Reagan’s second-term change or from Gorbachev’s new leadership.", title:"Main players of the end of the Cold War", when:"1979–91",
  q:"Who were the US Presidents and Soviet General-Secretaries in the 2nd Cold War and the New Détente?",
  pts:["2nd Cold War (1979–85), US: Carter (1977–81); Reagan (1981–89)",
       "2nd Cold War, USSR: Brezhnev (1964–82); Andropov (1982–84); Chernenko (1984–85)",
       "New Détente (1985–91), US: Reagan (1981–89); Bush (1989–93)",
       "New Détente, USSR: Gorbachev (1985–91)"] });

add("16.2 Reasons for US Renewed Containment", { id:"cw3-detente-limits", exp:"This reason explains renewed containment as a reaction to détente’s weaknesses: because détente rested on trust, Reagan believed the USSR had used it as cover to keep building arms. That belief led to the conclusion that only a show of strength could convince Moscow that further engagement with the USA was fruitless. It frames the debate on whether US policy was offensive ambition or a defensive response.", title:"Limitations of détente", when:"1970s–1980",
  q:"How did the limitations of détente and continuing Cold War concerns lead to US renewed containment?",
  pts:["Debate: continued US aggressive ambitions (offensive) or US defensive response to renewed Soviet provocation (defensive)?",
       "Détente was fundamentally based on trust/“gentleman's agreement” — cynics saw it as a new form of containment (like Peaceful Coexistence in the 1950s), a façade to lull the other side into complacency",
       "Reagan believed the US had been ‘tricked’ into détente while the USSR covertly continued arms buildup despite arms-control talks/treaties",
       "These historians argue the only way to end the Cold War was a show of strength, to persuade the USSR that continued engagement with the US was fruitless"] });
add("16.2 Reasons for US Renewed Containment", { id:"cw3-spanier-gaddis-detente", exp:"Both historians argue détente was containment by other means rather than an attempt to end the Cold War. Spanier ties it to the conditions of strategic parity and the Sino-Soviet split, while Gaddis says it was meant to freeze the conflict in place. Gaddis’s logic, that only killing détente could end the Cold War, supports the triumphalist case that Reagan’s confrontation was a necessary step towards the end.", title:"Spanier and Gaddis on détente", when:"1990 / 2006",
  q:"What did Spanier (1990) and Gaddis (2006) argue about détente?",
  pts:["Spanier (1990): détente was “essentially an adaptation of containment to an era of superpower strategic parity, Sino-Soviet schism and pseudo-isolationism in the United States”",
       "Spanier: US policy refocused on the stronger Soviet threat and moved closer to China",
       "Gaddis (2006): détente sought to “freeze the Cold War in place” rather than end it",
       "Reagan on détente: “Isn't that what a farmer has with his turkey—until Thanksgiving Day?”",
       "Gaddis: “because détente perpetuated—and had been meant to perpetuate—the Cold War, only killing détente could end the Cold War.”"] });
add("16.2 Reasons for US Renewed Containment", { id:"cw3-brezhnev-carter", exp:"The two doctrines show each superpower publicly declaring the right to use force to protect its sphere: the USSR in its bloc (Czechoslovakia 1968, Afghanistan 1979), the USA in the Persian Gulf. Carter’s doctrine shows that the US hardening had begun before Reagan, which qualifies how new renewed containment was. The Brezhnev Doctrine is also the benchmark against which Gorbachev’s later Sinatra Doctrine marks a decisive break.", title:"Brezhnev Doctrine vs. Carter Doctrine", when:"1968 / 23 Jan 1980",
  q:"Compare the Brezhnev Doctrine and the Carter Doctrine.",
  pts:["Brezhnev Doctrine (USSR, 1960s–70s): any threat to socialist rule in a Soviet-bloc state was a threat to them all — justified Soviet intervention",
       "Used to justify the 1968 occupation of Czechoslovakia; alluded to again for Afghanistan, 1979",
       "Carter Doctrine (US, 1977–81): US would use military force if necessary to defend Persian Gulf interests",
       "Carter, State of the Union, 23 Jan 1980: “an attempt by any outside force to gain control of the Persian Gulf region will be regarded as an assault on the vital interests of the United States… repelled by any means necessary, including military force”"] });
add("16.2 Reasons for US Renewed Containment", { id:"cw3-soviet-provocation", exp:"These actions support the ‘defensive’ reading of renewed containment: US hardening is presented as a response to Soviet behaviour. The pattern is that arms-control treaties failed to stop Soviet build-up through violations, loopholes and new technology, while Afghanistan killed SALT II and Third World competition grew. Note that this is the Western-centric reading, which blames Soviet provocation rather than US action.", title:"Provocative Soviet actions", when:"1963–1979",
  q:"Which Soviet actions provoked US renewed containment?",
  pts:["Soviet violation of human-rights promises in the Helsinki Final Act/CSCE (1975), seen as the climax of détente",
       "Covert Soviet ICBM buildup after realising inferiority post-Cuban Missile Crisis (1963) — nuclear parity by the 1970s, hence SALT I & the ABM Treaty (1972) to cap further buildup",
       "Arms race continued despite talks/treaties: treaties violated, loopholes exploited, fast-moving nuclear technology outpaced treaty coverage",
       "SALT II (1979) collapsed when the USSR invaded Afghanistan",
       "Increased 3rd World competition (decolonisation, African civil wars); continued Soviet build-up of missiles not covered by treaties (incl. INF)"] });
add("16.2 Reasons for US Renewed Containment", { id:"cw3-us-prestige", exp:"Gaddis explains the psychological driver: after Vietnam, Watergate, the loss of allies and the Tehran embassy humiliation, the USA seemed on the defensive everywhere while Moscow seemed on a roll. Renewed containment was therefore partly about restoring American confidence and credibility. The summary also warns that this explanation reflects Western-centric writers who place the blame on Soviet actions.", title:"Restoring American prestige", when:"1970s–1980",
  q:"How did the need to restore American prestige drive renewed containment (Gaddis, 2006)?",
  pts:["Gaddis (2006): “Americans seemed mired in endless arguments with themselves, first over the Vietnam War, then Watergate…”",
       "…then charges that Carter had failed to protect important allies like the Shah of Iran or Anastasio Somoza",
       "Low point: Iranians invaded the US embassy in Teheran",
       "This humiliation, closely followed by the Soviet invasion of Afghanistan a few weeks later, made it seem Washington was on the defensive everywhere and Moscow was on a roll",
       "Summary: Reagan's policy shaped/perpetuated by immediate factors 1980–85; Western-centric writers blame US actions on provocative Soviet actions rather than the reverse"] });

add("16.3 Key Features of US Renewed Containment", { id:"cw3-military-buildup", exp:"The collapse of arms talks after SALT I and SALT II removed the restraint of negotiation, so the USA turned to sheer build-up: the defence budget more than doubled, the navy expanded and new weapons systems were revived or accelerated. This is the core evidence for the Reagan Victory thesis that the USA deliberately used an arms race to strain the weaker Soviet economy.", title:"Military containment: the defence build-up", when:"1981–86",
  q:"What were the features of US military containment under Reagan (talks and defence build-up)?",
  pts:["ICBM talks collapsed after SALT I (1972) and again after SALT II (1979, over Afghanistan) — both continued building ICBMs; conventional-arms talks (MBFR 1972) also collapsed",
       "Defence budget: $171bn (1981) → $376bn (1986)",
       "Navy grew from 454 to a planned 600 ships (incl. 15 carrier groups)",
       "Revived B-1 bomber, accelerated MX ICBM & Trident submarine",
       "New BMD and anti-satellite (ASAT) systems"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-inf-deploy", exp:"The INF crisis shows the action-reaction cycle of the 2nd Cold War: Soviet SS-20s prompted NATO’s dual-track response, the Zero Option was rejected, and Pershing II deployment ended the talks. Its significance is two-sided: it revived fear of nuclear war and MAD, fuelling Western peace movements that pressured Reagan towards ending the Cold War, while also draining both economies.", title:"INF deployment and the Zero Option", when:"1976–Nov 1983",
  q:"How did the INF deployment crisis in Europe unfold, 1976–83?",
  clue:"Soviet SS-20s prompted NATO's Double-Track Decision; Reagan offered to forgo deployment if SS-4/5/20s were dismantled; talks ended when Pershing IIs arrived in West Germany.",
  pts:["Soviet SS-20s (from 1976) prompted the NATO Double-Track Decision (Dec 1979): (1) bilateral negotiations (Geneva, 1980); (2) INF modernisation (Pershing II & Cruise missiles) if talks failed",
       "Reagan's ‘Zero Option’/‘Zero-Zero’ (Nov 1981): NATO would forgo INF deployment if the USSR dismantled its SS-4/5/20s — well received by European publics but rejected by the USSR",
       "‘Walk in the woods’ (Nitze–Kvitsinsky, 1982) failed to break the deadlock",
       "Autumn 1983: US lowered proposed INF ceiling to 420 missiles; USSR proposed “equal reductions”",
       "Talks ended once Pershing IIs arrived in West Germany (Nov 1983)",
       "Renewed fear of nuclear war and MAD → anti-nuclear peace movements in the West pressured Reagan to end the Cold War; also diverted resources from both economies"] });
add("16.3 Key Features of US Renewed Containment", { id:"sdi", exp:"SDI was presented by Reagan as defensive, aiming to make nuclear weapons ‘impotent and obsolete’, but because it would neutralise Soviet missiles the USSR saw it as offensive. That gap in perception explains why it intensified the arms race and became a sticking point at summits. Its timing, just after the ‘Evil Empire’ speech amid failed talks, shows it belonged to the confrontational phase.", title:"Strategic Defense Initiative (SDI)", when:"23 Mar 1983",
  q:"What was the Strategic Defense Initiative — its origins, features and Reagan's justification?",
  clue:"‘Star Wars’: a 5-year, $26bn nationwide ballistic-missile shield programme announced 3 weeks after the ‘Evil Empire’ speech.",
  pts:["23 Mar 1983 (3 weeks after the ‘Evil Empire’ speech): 5-year, $26bn programme for a nationwide ballistic-missile defence system (‘Star Wars’)",
       "Preceded by NSDD-12 (early 1981) calling for “vigorous research and development” on BMD",
       "Envisioned ground- and space-based weapons (beam/particle weapons, lasers, homing rockets) to destroy Soviet missiles before they reached US targets",
       "Reagan (TV address, 1983): “What if free people could live secure in the knowledge that their security did not rest upon the threat of instant US retaliation… to give us the means of rendering these nuclear weapons impotent and obsolete.”",
       "Created against the backdrop of the 2nd Cold War and failed arms talks — seen by the USSR as an offensive mechanism despite Reagan's framing"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-sdi-impact-cw-us", exp:"SDI’s impact was contradictory. At home it boosted security and showcased US technological superiority, but abroad it blindsided allies who saw it as undermining MAD and feared losing the US nuclear umbrella. In superpower diplomacy it blocked agreement at Reykjavik, and the INF Treaty only came once SDI was separated from the talks, which suggests SDI could delay as well as drive the end.", title:"Impact of SDI on the Cold War, the USA and allies", when:"1983–87",
  q:"What was the impact of SDI on the Cold War, on the USA and on US allies?",
  pts:["Cold War: made the 1972 MBFR treaty's land-based limits obsolete; key sticking point at summits",
       "Reykjavik (1986) collapsed over Reagan's refusal to exclude SDI; INF Treaty (1987) only concluded once Gorbachev agreed to negotiate SDI separately",
       "USA: well received domestically — enhanced sense of security, showcased US technological superiority, reflected Reagan's personal/utopian vision",
       "Allies: blindsided many advisors; seen as ‘unexpected’, ‘outlandish’, ‘a fantasy’ that undermined MAD (reinforced by the 1972 ABM Treaty)",
       "Mitterrand feared loss of the US nuclear umbrella; European resistance had limited impact"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-sdi-impact-ussr", exp:"On the USSR, SDI worked as a propaganda and economic-pressure tool, forcing extra spending when defence already took 15–17% of GDP, and Gorbachev recognised it was meant to wear the USSR out. The notes’ verdict is balanced: it hastened the end by straining Soviet resources and pushing Gorbachev to reduce tensions, yet it also obstructed negotiations, so it was one hastening factor, not the sole cause.", title:"Impact of SDI on the USSR, its end, and verdict", when:"1983–1990s",
  q:"What was SDI's impact on the USSR, how did it end, and what is the notes' verdict?",
  pts:["Dobrynin: “you will be opening a new phase in the arms race.”",
       "Effective propaganda/economic-pressure tool (never actually intended as a bargaining chip) forcing extra Soviet ABM spending (Soviet defence budget ≈15–17% of GDP in 1983)",
       "Gorbachev later: “we should stop being afraid of SDI… they're pursuing this program to wear us out.” 1987 Soviet Energia/laser-missile launch to counter SDI failed",
       "End: funding plummeted in the early 1990s; renamed Ballistic Missile Defense Organization (BMDO) under Clinton, shifting to ground-based interceptors",
       "Verdict: hastened the end of the Cold War by straining Soviet resources, pushing Gorbachev to reduce tensions — yet obstructed negotiations until omitted from talks; one of many hastening factors, not the sole cause"] });
add("16.3 Key Features of US Renewed Containment", { id:"reagandoctrine", exp:"The Reagan Doctrine shifted the method from containing to ‘rolling back’ Soviet-backed regimes by arming anti-communist guerrillas, which kept US troop casualties low. However, its aim of reducing Soviet influence was the same as earlier policy, so it is best seen as an intensified version of containment rather than a total break. The Mujahedeen example shows the long-term risk of backing proxies.", title:"The Reagan Doctrine", when:"6 Feb 1985",
  q:"What was the Reagan Doctrine and how did it differ from earlier US policy?",
  clue:"Announced in the 1985 State of the Union: “Support for freedom fighters is self-defense.”",
  pts:["SOTU 1985: “We must not break faith with those who are risking their lives— on every continent from Afghanistan to Nicaragua – to defy Soviet-supported aggression… Support for freedom fighters is self-defense.”",
       "Jan 1977 Reagan: “my idea of American policy toward the Soviet Union is simple… we win and they lose.”",
       "Replaced containment/détente with ‘roll-back communism’: overt/covert support to anti-communist guerrillas to ‘roll back’ Soviet-backed governments in Europe and the 3rd World",
       "Lowered cost/casualties of direct US troop involvement (though some backed forces, e.g. Afghan Mujahedeen, later turned against the USA)",
       "Objectives similar to past US policy (reduce Soviet influence) though approach differed — a belated response enhancing earlier containment/détente, intensifying 3rd World competition after decolonisation"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-rd-afghan-nicaragua", exp:"These two cases show both the reach and the problems of the doctrine. Afghanistan aid actually began under Carter, which weakens claims of Reagan’s originality, though supporters credit it with the Soviet defeat. Nicaragua shows the legal and moral cost: Iran-Contra and the ICJ ruling that the USA ignored. Both are useful evidence when assessing whether US pressure really ended Soviet influence.", title:"Reagan Doctrine: Afghanistan and Nicaragua", when:"1979–89",
  q:"How was the Reagan Doctrine applied in Afghanistan and Nicaragua?",
  pts:["Afghanistan: CIA sent $2bn+ in weapons/aid to the Mujahedeen (1979–89), predating the Doctrine, originating with Carter's NSA Brzezinski; channelled via Pakistan's ISI",
       "Pro-US view: credited with ending Soviet occupation/military defeat (1989)",
       "Nicaragua: US military support to the ‘contras’, funded partly via illegal arms sales to Iran (Iran-Contra affair) after Congress blocked funding",
       "ICJ (1984) ruled against the US for supporting the rebellion/mining Nicaraguan waters — US refused to comply, blocked enforcement via UNSC veto",
       "War ended when the Sandinistas lost 1989 elections"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-rd-others", exp:"These cases show how widely the doctrine was applied, from Africa to Asia to Europe. Advocates credit US pressure for outcomes like the 1989 removal of Soviet and Cuban troops from Angola. Poland is the key link to Topic 3’s People Power theme, since covert US funding of Solidarity and sanctions after martial law connect American policy to the Eastern European movements.", title:"Reagan Doctrine: Angola, Ethiopia, Cambodia, Poland", when:"1980s",
  q:"How was the Reagan Doctrine applied in Angola, Ethiopia, Cambodia and Poland?",
  pts:["Angola: US backed Jonas Savimbi's UNITA against the pro-Soviet MPLA; 1989 agreement removed Soviet/Cuban troops — credited by advocates to Savimbi/US pressure",
       "Ethiopia: US blamed famine on the Soviet-backed Mengistu government's agricultural/military policies; noted Soviet naval/air presence in Eritrea's Red Sea ports",
       "Cambodia: covert US aid to the smaller KPNLK resistance group (not the Khmer-Rouge-linked largest group, due to its human-rights record)",
       "Poland: CIA covertly funded Solidarity (Lech Wałęsa); after Jaruzelski's martial law (Dec 1981), Reagan imposed economic sanctions on Poland and the USSR"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-rd-verdict", exp:"The verdict is double-edged: the USA over-extended itself in the Third World without major gains, but because the USSR’s economy was in a worse state, the same competition drained Soviet resources even more. The burden on both sides helped push them towards ending the Cold War. Thatcher’s view supports the triumphalist reading, though the notes frame the doctrine as one contributor among several.", title:"Verdict on the Reagan Doctrine", when:"1980s",
  q:"What is the notes' verdict on the Reagan Doctrine?",
  pts:["The USA over-extended its 3rd World commitments without significant prospective gains, dissipating resources and forcing an end to the Cold War",
       "It also drained Soviet resources further given the USSR's worse economic state",
       "Thatcher credited the Doctrine with helping end the Cold War"] });
add("16.3 Key Features of US Renewed Containment", { id:"cw3-econ-propaganda", exp:"Economic containment targeted Soviet vulnerability: as a net oil exporter, the USSR lost revenue when the USA got Saudi Arabia to depress oil prices, although Reagan failed to stop the European pipeline deal. The propaganda speeches framed the struggle as moral and spiritual and rejected spheres of influence in Eastern Europe. Together they support the claim that rhetoric persuaded the USSR further engagement was fruitless.", title:"Economic containment and the propaganda war", when:"1982–84",
  q:"What were the features of US economic containment and the propaganda war?",
  pts:["USA persuaded Saudi Arabia to raise oil output, depressing world oil prices to worsen Soviet oil-export revenues (USSR a net oil exporter)",
       "Reagan tried (unsuccessfully) to force Western European allies to abandon the gas-oil pipeline deal with the USSR",
       "June 1982 (British Parliament): condemned totalitarianism; no communist regime had “been able to risk free elections”; called for fostering “the infrastructure of democracy”",
       "March 1983 ‘Evil Empire’ speech: urged against seeing both sides as “equally at fault”; struggle ultimately “a spiritual one… a test of moral will and faith” rather than “bombs or rockets”",
       "Aug 1984: rejected “permanent subjugation of the people of Eastern Europe” and any reading of Yalta as US consent to spheres of influence"] });

add("16.4 How US Renewed Containment Led to the End of the Cold War", { id:"cw3-rv-thesis", exp:"The Reagan Victory thesis argues the USA deliberately used an arms race based on technological superiority to bankrupt the USSR. The evidence is the cost imbalance: Soviet defence rose to 27% of GDP at the expense of civilian industry, and Mujahedeen aid cost Moscow eight times what it cost Washington. In this view economic strain plus rhetorical pressure forced the USSR to give up confrontation.", title:"Reagan Victory thesis: bankrupting the USSR", when:"1980–85",
  q:"How, according to the Reagan Victory thesis, did US renewed containment lead to the end of the Cold War?",
  pts:["Powaski: “The USA wanted to use an arms race—one that would emphasize America's technological superiority—to strain and bankrupt the Soviet economy.”",
       "Reagan (memoirs): “I intended… to let the Soviets know that we were going to spend what it took to stay ahead of them in the arms race.” — a senior official called it “a full court press”",
       "Lt. Gen. Daniel O. Graham: SDI would “severely tax, perhaps to the point of disruption, the already strained Soviet technological and industrial resources.”",
       "1980–85: USSR forced to raise defence spending from 22% to 27% of GDP, at the expense of consumer/civilian industries",
       "US covert Mujahedeen support (≈$1bn/yr) cost the Soviets roughly eight times as much",
       "It was Reagan (via the rhetoric war) who persuaded the USSR that further engagement with the US was fruitless"] });
add("16.4 How US Renewed Containment Led to the End of the Cold War", { id:"cw3-soviet-counter", exp:"This card shows the USSR was not just a passive victim of US pressure: its own counter-measures, such as heavy-industry defence spending, SS-20 build-up, support for the Sandinistas and UNITA and the war in Afghanistan, drained its resources. That links the triumphalist argument to Soviet choices and helps explain why, by 1985, Gorbachev needed to pivot away from costly confrontation.", title:"Costly Soviet counter-measures", when:"1980–85",
  q:"How did the USSR's own responses to US containment strain its resources?",
  pts:["Heavy-industry concentration (15% on defence, Hanson)",
       "ICBM/INF buildup (SS-20s)",
       "Continued 3rd World competition (Sandinistas, UNITA)",
       "The Afghan ‘bleeding wound’ (≈$20bn/yr, casualties, negative public opinion)",
       "Strained resources ahead of Gorbachev's post-1985 pivot"] });
add("16.4 How US Renewed Containment Led to the End of the Cold War", { id:"cw3-us-cost", exp:"Renewed containment hurt the USA too, worsening its twin deficits and delaying domestic reform, which put pressure on Reagan to change course. The key comparison is that the bigger, more productive US economy could afford ‘guns as well as butter’ while the stagnant Soviet economy could not. This asymmetry is why the arms race strained the USSR far more and is central to the triumphalist argument.", title:"Cost of renewed containment to the USA", when:"1980s",
  q:"What did renewed containment cost the USA, and why was the impact less severe than on the USSR?",
  pts:["Worsened US twin deficits (trade + budget) as resources were diverted to defence — pressuring Reagan too",
       "Schulzinger (1994): “the Cold War delayed the badly needed domestic reforms and damaged the US economy.”",
       "Impact less severe on the USA (larger resource base) than the USSR (economy stagnant since the 1960s)",
       "Vadney (1998): “the arms race was less affordable for the USSR than the USA.”",
       "Walker (1993): the West prevailed because it could supply “guns as well as butter… for an ever-increasing proportion of its taxpayers.”"] });
add("16.5 Limitations of the Reagan Victory School", { id:"cw3-rv-limits", exp:"The main critique is a missing causal link: in Reagan’s first term the USSR did not bend, staying in Afghanistan and matching the arms race, and the KAL shoot-down suggests panic rather than surrender. Soviet economic problems also predated Reagan, so he at most made existing weaknesses worse. This is the evidence to use when arguing that Gorbachev and the people matter more.", title:"Limitations of the Reagan Victory School", when:"1981–85",
  q:"What are the limitations of the Reagan Victory School?",
  pts:["No clear causal link/direct evidence the Soviets were ‘bending’ in Reagan's 1st term: stayed in Afghanistan, Iron Curtain remained, arms race escalated (SS-20s met with Pershing/Cruise)",
       "SDI may even have slowed the end of the Cold War as a recurring summit sticking point",
       "Soviet resolve stiffened: Pravda warned Reagan's rhetoric risked “catastrophe”; Gaddis: 1983 Korean Airlines shoot-down (269 dead) reflected Kremlin panic, not capitulation",
       "Attributing perestroika/glasnost to Reagan is tenuous — Soviet problems long predated Reagan (Brezhnev-era stagnation, command-economy flaws); Reagan at most exacerbated existing weaknesses",
       "Ignores fundamental USSR weaknesses and the roles of Gorbachev and ‘the people’"] });

/* ── 17. US Role in Arms Control Negotiations (1985–89) ── */
add("17.1 Reasons for the Shift", { id:"cw3-shift-reasons", exp:"Reagan’s second-term shift came from several pressures working together: electoral politics against Mondale’s arms-control promise, the wish to improve relations with Western Europe, the scare of Able Archer 83, and personalities like Shultz plus rapport with Gromyko and Gorbachev. This shows US policy changed for its own reasons, which supports giving Reagan some credit, not only Gorbachev.", title:"Reasons for Reagan's shift to cooperation", when:"1984–85",
  q:"Why did Reagan's 2nd term shift from containment to cooperation (1985–89)?",
  pts:["Re-election (1984) vs Walter Mondale, who promised arms-control talks within six months — Reagan needed to show firmness and capacity for good relations",
       "Gaddis (2007): the shift also improved relations with Western Europe, where détente had never been as unpopular as in the US",
       "Self-awareness: Able Archer 83 (see separate card) convinced Reagan he had pushed the Russians far enough",
       "Personalities: George Shultz (Secretary of State from June 1982) held a more realistic view of nuclear parity — “must be given credit for the hard work and skill… in the face of much opposition from hard-liners” (Powaski)",
       "Autumn 1984: Reagan's first meeting with Foreign Minister Gromyko — rhetoric moderated on both sides (Gaddis, 2007)",
       "Geneva (1985): Reagan and Gorbachev “had come to like and respect each other” despite Reagan remaining unconvinced by Gorbachev's beliefs (Farnham, 2001)"] });
add("17.1 Reasons for the Shift", { id:"cw3-able-archer", exp:"Able Archer 83 matters because it revealed how close confrontation had come to nuclear war: Soviet leaders briefly believed an attack was imminent. Gaddis argues this convinced Reagan he had pushed the Russians far enough, so it is a turning point from confrontation towards cooperation. It also shows that fear of nuclear war, not only economic strain, drove the shift.", title:"Able Archer 83", when:"1983",
  q:"Why was Able Archer 83 significant for Reagan's shift (Gaddis, 2007)?",
  clue:"A 1983 NATO exercise that led Andropov and his aides to conclude briefly that a nuclear attack was imminent.",
  pts:["Soviet intelligence caused Andropov and his top aides to conclude—briefly—that a nuclear attack was imminent",
       "“It was probably the most dangerous moment since the Cuban Missile Crisis”",
       "“The Able Archer crisis convinced [Reagan] that he had pushed the Russians far enough.”"] });
add("17.2 Manifestations of US Cooperation and Accommodation", { id:"cw3-summits", exp:"The annual summits show the new détente as a cumulative process: personal rapport at Geneva led to near-agreement at Reykjavik, which made the INF Treaty possible, and later meetings under Bush delivered CFE and START I. Malta produced no treaties yet marks the official end, showing the end of the Cold War was about relaxed relations and trust rather than a single agreement.", title:"Annual superpower summits 1985–91", when:"1985–91",
  q:"List the annual superpower summits from 1985 to 1991 and their outcomes.",
  pts:["1985 Geneva: established personal rapport between Reagan and Gorbachev",
       "1986 Reykjavik: collapsed at the last minute over SDI, but a breakthrough that facilitated the INF Treaty",
       "1987 Washington DC: INF Treaty signed; 1988 Moscow: INF ratified by US Senate (May 1988), regional issues and human rights discussed",
       "1989 Malta: Bush–Gorbachev; no agreements signed, but widely viewed as the official end of the Cold War",
       "1990 Washington DC/Paris: Chemical Weapons Accord; CFE Treaty",
       "1991 Moscow: START I signed"] });
add("17.2 Manifestations of US Cooperation and Accommodation", { id:"inf", exp:"The INF Treaty was a breakthrough because it eliminated a whole category of nuclear weapons rather than just capping them, proving the arms race could be reversed. It became possible only once Gorbachev conceded on SDI, British and French missiles, asymmetrical cuts and verification, and the USSR dismantled about twice as many missiles. That pattern supports the Soviet initiative argument, while showing the treaty still needed US negotiation.", title:"INF Treaty", when:"Dec 1987",
  q:"What were the terms and significance of the INF Treaty (1987)?",
  clue:"Washington 1987 agreement — the first to eliminate an entire category of nuclear weapons.",
  pts:["Signed once Gorbachev agreed to exclude SDI and British/French missiles, accept asymmetrical reductions and on-site verification",
       "Banned all land-based missiles of 1,000–5,500km range plus 500–1,000km SRINF",
       "US dismantled ≈859 Pershing/Tomahawk missiles; USSR ≈1,752 missiles",
       "First treaty to eliminate an entire category of nuclear weapons",
       "Mason: “a milestone… it showed that it was possible not merely to restrain but to reverse the arms race.”"] });
add("17.2 Manifestations of US Cooperation and Accommodation", { id:"cw3-cfe-cw-start", exp:"These treaties show disarmament widening after INF from intermediate missiles to conventional forces, chemical weapons and strategic nuclear arms. START I’s history is revealing: proposed by Reagan in 1982, it was held up by non-negotiable terms, INF deployment and SDI, then sped up after Reykjavik and INF. That shows how trust built step by step, and Bush’s role in finishing it shows US continuity after Reagan.", title:"CFE, Chemical Weapons Accord and START I", when:"1989–91",
  q:"What did the CFE Treaty, the Chemical Weapons Accord and START I achieve?",
  pts:["CFE (1989, Malta): reduced NATO/Warsaw Pact land forces in Europe; comprehensive limits + mandated destruction of excess equipment",
       "Chemical Weapons Accord (1989, Malta): reduced chemical stockpiles to ≤5,000 agent tons by end-2022; allowed on-site inspection",
       "START I (1991, Moscow): proposed by Reagan (1982); largest/most complex arms treaty in history — removed ≈80% of existing strategic nuclear weapons in 2 phases",
       "START I delayed pre-1985 by non-negotiable terms, then by 1983 INF deployment/SDI; accelerated after Reykjavik (1986) and the INF Treaty (1987)",
       "START I obligations passed to 12 USSR successor states after Dec 1991"] });
add("17.2 Manifestations of US Cooperation and Accommodation", { id:"cw3-unilateral-cuts", exp:"The significance of these cuts is that Gorbachev made them without demanding anything back, which broke the long-standing Western suspicion of Soviet intentions and started a positive cycle of reciprocity. Dropping opposition to SDI removed a key obstacle to further disarmament. This is strong evidence for the Soviet initiative school, as Moscow abandoned its forty-year approach of managing the Cold War through rivalry.", title:"Unilateral Soviet cuts and their significance", when:"Dec 1988–1989",
  q:"What unilateral Soviet concessions were made, and what was their significance?",
  pts:["Dec 1988: Gorbachev announced a 500,000-troop reduction within 2 years (no reciprocity expected)",
       "Plus removal of 10,000 tanks from Europe (incl. 5,000 from East Germany/Czechoslovakia/Hungary)",
       "1989: Gorbachev dropped opposition to SDI, removing a key roadblock to further disarmament",
       "Significance (1): started a positive action-reaction cycle of trust/reciprocity, breaking “the traditional suspicion of Soviet intentions” (Lightbody)",
       "Significance (2): fundamental reorientation — the USSR no longer intended to manage the Cold War with the US as it had for the previous 40 years"] });
add("17.2 Manifestations of US Cooperation and Accommodation", { id:"cw3-arms-obstacles", exp:"Even after 1985 progress was not smooth: the two leaders disagreed on SDI and on whether talks should be linked to human rights and Afghanistan, and both faced domestic crises and critics. Lingering US distrust until the Wall fell shows that cooperation was fragile. Use this to qualify any argument that the post-1985 détente made the end of the Cold War inevitable or easy.", title:"Continued obstacles to arms control after 1985", when:"1985–89",
  q:"What obstacles to arms control remained after 1985?",
  pts:["Reagan wanted continued SDI research despite Gorbachev's suspicion (Gorbachev proposed banning all ballistic missiles instead)",
       "Reagan wanted to link talks to human rights/Soviet Jewish emigration/Afghanistan; Gorbachev wanted arms-control-only talks",
       "Strains on Reagan: 1987 stock-market crash, Iran-Contra scandal",
       "Strains on Gorbachev: opposition to reforms, the Mathias Rust incident, the Yeltsin affair",
       "Some American politicians still distrusted Gorbachev right up to the fall of the Berlin Wall (Nov 1989)"] });
add("17.3 Economic Cooperation and Rhetoric", { id:"cw3-econ-coop", exp:"Reagan’s ‘kiss of life’ of trade, aid and loans was meant to help Gorbachev shift resources from defence to the economy, but Bredenkamp warns Western help could only play a supporting role given the USSR’s size. The rhetoric shows how the tone changed from confrontation to partnership, ending with Malta’s talk of burying the Cold War, which underlines that the end was about changed relations.", title:"Economic cooperation and rhetoric", when:"1985–89",
  q:"What forms did US–Soviet economic cooperation and conciliatory rhetoric take after 1985?",
  pts:["Reagan provided a ‘kiss of life’ — trade, aid, investment and IMF/World Bank loans — to support Gorbachev's reforms and divert resources from defence to the economy",
       "Bredenkamp (1991): “the sheer size of the USSR gives Western assistance at most a supporting role… ultimate success will depend on the efforts and determination of the Soviet people themselves”",
       "Geneva 1985, Gorbachev: “I have come to seek a fresh start”",
       "Brandenburg Gate, June 1987, Reagan: “Mr. Gorbachev, open this gate. Mr. Gorbachev, tear down this wall” (fell 10 months later, 1 year after Reagan effectively left office)",
       "Malta 1989, Gorbachev: “We are at the beginning of a long road to a lasting and peaceful era”; his spokesman: “We bury the Cold War at the bottom of the Mediterranean sea.”"] });
add("17.4 Limitations of the Post-1985 US Accommodation Argument", { id:"cw3-accom-limits", exp:"These limitations challenge any claim that US accommodation ended the Cold War. Reagan was slow to trust Gorbachev, made firm demands before signing INF, and was mostly reacting to Soviet initiatives, as Schweitzer’s remark suggests; US aid was also too small to rescue the Soviet economy. Together they shift weight towards Gorbachev as the driver, with Reagan as the responsive partner.", title:"Limits of the US accommodation argument", when:"1985–89",
  q:"What are the limitations of the argument that post-1985 US accommodation ended the Cold War?",
  pts:["Reagan took years to ‘warm up’ to Gorbachev, adopting a wait-and-see attitude rather than trusting the ‘charm offensive’",
       "Reagan remained intransigent on excluding SDI/British-French missiles and demanding on-site verification/asymmetrical reduction before signing INF",
       "Reagan was largely surprised by and responding to Gorbachev's initiative — Schweitzer (2002): “Reagan happened to be there when Gorbachev ended the Cold War.”",
       "US economic support was insufficient to save the USSR (Bredenkamp, 1991)"] });
add("17.5 Concluding Evaluation — Sections 16–17", { id:"cw3-reagan-eval", exp:"The judgement is that Reagan was necessary but not sufficient. He did not start the process, which came from the Soviet side, but he kept it going through summits and diplomacy, and his restraint over Eastern Europe avoided provoking a hard-line Soviet reaction. This gives you a nuanced line for essays: credit Reagan for sustaining and permitting the end, not for initiating it.", title:"Concluding evaluation of Reagan's role", when:"1981–89",
  q:"What is the concluding evaluation of Reagan's role in ending the Cold War (Sections 16–17)?",
  pts:["Any explanation of 1989 must involve Reagan, but his role is necessarily a qualified one",
       "Less important in initiating the process culminating in the end of the Cold War",
       "Crucial in sustaining it through direct US–Soviet diplomacy",
       "Allowed it to conclude by remaining a largely passive observer of events in Eastern Europe (avoiding provoking a hard-line Soviet response)",
       "Next cluster of explanations: Gorbachev and the USSR itself"] });

/* ── 18. Decline of the USSR and Shifts in Soviet Foreign Policy ── */
add("18.1 What Exactly Was the Soviet Union?", { id:"cw3-ussr-what", exp:"Understanding that the USSR was a multinational union of republics ruled from Moscow explains why its collapse was a different event from the 1989 loss of the Eastern European satellites, which were never part of the Union. Lundestad shows that in 1991 the state, communist dictatorship and planned economy all ended together. The break-up mattered for the Cold War by removing the USA’s object of containment.", title:"What the Soviet Union was", when:"1924–1991",
  q:"What exactly was the Soviet Union, and why must its break-up be distinguished from 1989?",
  pts:["USSR (formed 1924): Russia (RSFSR) plus 14 non-Soviet republics incorporated 1924–1956, ruled from Moscow under the CPSU",
       "Broke up in Dec 1991 into 15 independent republics, some joining the CIS",
       "Lundestad: “In 1991 three processes culminated…: the Soviet Union collapsed, the communist dictatorship was done away with, and a sort of market economics, however precarious, was instituted… concurrent and highly interdependent.”",
       "The 1989 breakaway of Eastern European satellites (pro-Soviet but not officially part of the Union) is NOT synonymous with the 1991 break-up of the USSR",
       "The Cold War ended before the break-up and did not require it — but the break-up removed the USA's object of containment, definitively reorienting American foreign policy"] });
add("18.1 What Exactly Was the Soviet Union?", { id:"cw3-republics", exp:"The groups had very different interests, which explains how the Union fractured: the prosperous, recently annexed Baltics wanted out, the Slavic republics led the declaration that ended the USSR, the Trans-Caucasus was unstable, and the poor Central Asian republics wanted to stay. This diversity helps explain why nationalism, released by Gorbachev’s reforms, broke the USSR apart.", title:"Groups of Soviet republics", when:"to 1991",
  q:"Describe the five groups of Soviet republics and their features.",
  pts:["RSFSR/Russian Federation (1): first created (1917), largest; capital Moscow most important to protect",
       "Baltic Republics (3 — Lithuania, Latvia, Estonia): most vocal/prosperous; last forcibly incorporated; keen to break away; chose not to join the CIS",
       "Slavic republics (3 — Byelorussia, Ukraine, Georgia): relatively active, not so poor; led the declaration ending the USSR and creating the CIS (early Dec 1991)",
       "Trans-Caucasus (3 — Armenia, Azerbaijan, Moldavia): most unstable (e.g. Armenia–Azerbaijan conflict over Nagorno-Karabakh)",
       "Central Asian Republics (5 — Tadzhikistan, Uzbekistan, Kazakhstan, Turkmenistan, Kirgizistan): poorest; wished to remain in the USSR; non-Russian Muslim republics bordering Iran/Afghanistan"] });
add("18.2 Key Milestones in the Decline of the USSR", { id:"cw3-milestones-85-89", exp:"The 1985–89 milestones show Gorbachev’s reforms creating the problems that weakened the Union: perestroika worsened the economy and split the CPSU, glasnost and elections allowed opposition and nationalism, and 1989 saw unrest in Georgia and the Baltics alongside the loss of Eastern Europe. Note that the Cold War was declared over in Dec 1989 while the USSR still existed.", title:"Milestones of Soviet decline 1985–89", when:"1985–89",
  q:"What were the key milestones in the decline of the USSR from 1985 to 1989?",
  pts:["1985 May: anti-alcoholism campaign (detrimental socio-economic impact)",
       "1986: Perestroika introduced — exacerbated problems; divided CPSU (conservatives: too fast; reformers: too slow/limited)",
       "1987: Glasnost, decentralisation, democratisation, elections; Nov: Gorbachev–Yeltsin feud, Yeltsin ousted",
       "1989 Apr: Tbilisi massacre (Georgia, 21 dead); Jun: free contested elections; Poland/Hungary/Czechoslovakia/Romania elect non-communist leaders (Velvet Revolutions); end of Brezhnev Doctrine; Berlin Wall falls; Germany unified",
       "1989 Aug: 2m-strong Baltic human chain protest; Dec: Bush–Gorbachev declare Cold War over; Gorbachev responds to separatism with Law of Secession, 9+1/Union Treaty"] });
add("18.2 Key Milestones in the Decline of the USSR", { id:"cw3-milestones-90-91", exp:"These milestones show power draining from Gorbachev to Yeltsin and the republics: Gorbachev took an unelected presidency while Yeltsin won a popular mandate, the Warsaw Pact dissolved, and the failed coup led to the Minsk Declaration and Gorbachev’s resignation. The final point explains the irony: he was admired abroad for ending the Cold War but lost the support needed to keep the CPSU and USSR.", title:"Milestones of Soviet decline 1990–91", when:"1990–91",
  q:"What were the key milestones in the decline of the USSR in 1990–91?",
  pts:["1990 Mar: Gorbachev becomes 1st (unelected) Executive President of the USSR; Nov: Shevardnadze resigns (‘Dictatorship’ speech)",
       "1991 Mar: Warsaw Pact and COMECON formally dissolved",
       "12 Jun 1991: Yeltsin democratically elected 1st President of Russia, declares Russian independence (57.3% of votes)",
       "19–21 Aug 1991: conservative coup; 7 Dec: Minsk Declaration (Belarus, Russia, Ukraine) ends the USSR, creates the CIS",
       "21 Dec: 11/15 republics break away; 25–31 Dec: Gorbachev resigns, replaced by Yeltsin",
       "Gorbachev: classic leader highly regarded abroad but despised/isolated at home — lost power to maintain both CPSU and USSR"] });
add("18.3 Long-Term (1945–84) Causes of Decline", { id:"cw3-structure", exp:"This long-term cause explains why the USSR was vulnerable to break-up: many nationalities had been incorporated by force with uneven development, and Russians were barely a majority. Hobsbawn’s point is that the nationalist fracture was built into the system but stayed dormant until 1988, which shows Gorbachev’s reforms triggered rather than created separatism. Coleman’s phrase places the start of collapse at the edges.", title:"Structure and composition of the USSR", when:"1924–1988",
  q:"How did the structure and composition of the USSR contribute to its decline?",
  pts:["Too many republics/non-Russians forcibly incorporated since 1924, with uneven development",
       "Russians just over 50% of the population, with non-Russian enclaves even within Russia (Chechens, Tatars)",
       "Hobsbawn (1999): “nationalist fracture was potentially built into the system, although… separatism was not even thought of before 1988.”",
       "Coleman (1996): “the rot began at the border.”"] });
add("18.3 Long-Term (1945–84) Causes of Decline", { id:"sovietdecline", exp:"The planned economy rewarded quantity, loyalty and heavy industry rather than quality, talent and consumer goods, and planners lacked accurate information, so shortages and a black market hid an ‘invisible crisis’. Powaski’s point is that it became critical when the USSR could not keep up with Western technology, widening the gap in the 1980s. This shows Soviet decline was structural and predated Reagan.", title:"Inefficiencies of the centrally planned economy", when:"1945–84",
  q:"What inefficiencies of the centrally planned economy caused long-term Soviet decline?",
  clue:"Quotas over quality, heavy industry over consumer goods, and a tolerated black market masking an ‘invisible crisis’.",
  pts:["Over-focus on quotas/quantity over quality; manpower over technology; political loyalty over talent; heavy industry over consumer goods",
       "Centralisation/5-year plans; nationalisation; role-model incentives over financial ones; agricultural collectivisation; cumbersome bureaucracy",
       "Planners lacked accurate information → shortages → reliance on a (tolerated) black market masking an ‘invisible crisis’ behind apparent stability",
       "Powaski (1997): crisis turned critical once the USSR could no longer produce/absorb technological innovations (esp. computing) driving Western expansion",
       "Output gap widened in the 1980s for the first time in post-war history"] });
add("18.3 Long-Term (1945–84) Causes of Decline", { id:"cw3-khrushchev", exp:"Khrushchev’s reforms show the pattern of failed Soviet reform: de-Stalinisation opened space for dissent without weakening conservatives, his farming schemes led to food shortages and riots, and grain imports made the USSR dependent on the USA. His foreign policy kept resources flowing into the arms race and empire. These are long-term roots of the weaknesses Gorbachev inherited.", title:"Weak policies: Khrushchev", when:"1953–64",
  q:"How did Khrushchev's policies weaken the USSR (political, socio-economic, external)?",
  pts:["Political: Secret Speech/de-Stalinisation but failed to reduce conservative power; emergence of dissent",
       "Socio-economic: un-sustained reforms; Virgin Lands scheme, agro-town policy → food shortages, Novocherkassk riots (1962)",
       "Start of grain imports from USA (vulnerability to ‘blackmail’)",
       "External: peaceful coexistence & revived Cold War; resources diverted to arms race/3rd World/Eastern Europe/China"] });
add("18.3 Long-Term (1945–84) Causes of Decline", { id:"cw3-brezhnev-era", exp:"Brezhnev’s era is the key period of stagnation: political repression and a privileged loyalty class were paired with half-hearted economic reforms, so a hidden crisis grew behind apparent stability. Lightbody’s figures on falling industrial growth and descriptions of empty shops show the economy was failing well before Reagan, while short-lived successors could do little. This supports the argument that decline was internal.", title:"Weak policies: Brezhnev, Andropov, Chernenko", when:"1964–85",
  q:"How did Brezhnev, Andropov and Chernenko contribute to Soviet decline?",
  pts:["Brezhnev political: re-Stalinisation, personality cult, nomenklatura loyalty class, suppression of dissent (russification)",
       "Brezhnev socio-economic: limited/un-sustained Kosygin-Liberman reforms; invisible crisis behind a mask of stability; poor work discipline, alcoholism, low living standards; external: détente and Cold War",
       "Andropov (1983–84)/Chernenko (1984–85): limited political and socio-economic action; 2nd Cold War, negative impact",
       "Lightbody (1999): “The most significant weakness was the Soviet economy… annual growth rates for industrial output dropped steadily from an estimated 5.25 per cent in 1967 to 2 per cent by 1980”",
       "Lightbody: 1970s life was “empty shops, poor housing, subsistence diets, intense pollution and the return to a barter economy.”"] });
add("18.3 Long-Term (1945–84) Causes of Decline", { id:"cw3-social-divide", exp:"The gap between the privileged nomenklatura and ordinary workers, almost four times in pay plus special shops and dachas, undermined the system’s claim to equality. Because workers gained nothing from working harder, there was no incentive to raise production, which helps explain Soviet economic stagnation. It also shows why the CPSU elite had reason to resist reforms that threatened its privileges.", title:"The social divide (nomenklatura)", when:"Brezhnev era",
  q:"What was the social divide in the USSR and why did it matter?",
  pts:["Brezhnev-era growth of the nomenklatura (≈19m CPSU members)",
       "Had private shops, hospitals, dachas, resorts, vs. the wider population",
       "Average worker earned 195 roubles/month vs. ≈750 for the average nomenklatura member (Lightbody, 1999)",
       "No incentive to improve production"] });
add("18.3 Long-Term (1945–84) Causes of Decline", { id:"cw3-external-causes", exp:"External costs mattered: Soviet defence took far more of GNP than in the West, and both the Third World and Eastern Europe had become drains rather than assets. But the evaluation is crucial: since economic problems existed from the 1960s while foreign policy stayed hostile until 1985, decline alone cannot explain the shift. Gorbachev, Reagan’s softer second term and nuclear fear were the immediate triggers.", title:"External causes of Soviet decline", when:"1965–85",
  q:"What were the external (Cold War) causes of Soviet decline, and how should their impact be evaluated?",
  pts:["Defence spending rose from 12–14% of GNP (1965) to 15–17% (1985), some estimates 25% — vs 2–5% in Western/Eastern Europe and 6–7% in the US (Powaski, 1997)",
       "Cost of empire: 3rd World subsidies (Cuba, Vietnam, Afghanistan, Ethiopia) rose from ≈1% to ≈3% of GNP (1971–80)",
       "Eastern Europe shifted from Soviet asset (post-WWII extraction) to net cost by the 1970s (cheap oil/gas sold, poor-quality imports bought at high prices) (Lundestad, 2003)",
       "Evaluation: economic problems pre-dated 1985 (since the 1960s) yet foreign policy stayed confrontational until Gorbachev — decline alone did not cause a timely shift",
       "More immediate triggers: Gorbachev's ascension (1985), Reagan's more conciliatory 2nd term, fear of nuclear war from the INF race"] });
add("18.4 Impact of Perestroika and Glasnost", { id:"perestroika", exp:"Perestroika failed because it was caught between two camps. It went far enough to disrupt the old system and anger conservatives who lost power, but not far enough to create a working market, as big enterprises kept weak incentives and shortages and inflation continued. Falling oil prices and limited Western aid took away any cushion, so the reforms made Soviet decline worse rather than reversing it.", title:"Perestroika", when:"from 1986",
  q:"What was perestroika and why did it fail?",
  clue:"Gorbachev's economic restructuring from 1986: decentralised controls, self-financing enterprises, the 500-Day Plan.",
  pts:["Economic restructuring from 1986: decentralised controls, self-financing enterprises, reduced direct CPSU involvement in governance",
       "Conservatives resented anti-alcoholism campaign, black-market crackdown, decentralisation, half-hearted capitalist laws (state enterprises, cooperatives, individual labour, Yeltsin-Shatalin 500-Day Plan/‘shock therapy’)",
       "Large state enterprises kept limited incentives/accountability; continuing food shortages, high prices, inflation",
       "Political resistance: power transfer from central planners to regional managers; loss of the Eastern European empire meant loss of profits/taxes/resources (though satellites more liability than asset by the 1980s)",
       "Oil-price collapse (mid-1980s) and limited Western aid failed to give the ‘kiss of life’; agricultural reforms belated/ineffective (memory of Stalin's Kulak policy; no real land privatisation)",
       "Growing disenchantment as resources kept flowing to defence rather than consumers"] });
add("18.4 Impact of Perestroika and Glasnost", { id:"cw3-white-economy", exp:"White’s evidence shows that Gorbachev’s reforms made living standards worse, not better: shortages and quality both deteriorated, the black market grew and up to a quarter of the population fell into poverty. The 1991 fall in national income, worse than the US Depression in relative terms, explains why faith in Gorbachev and the system collapsed at home, contributing to the USSR’s end.", title:"White on the economic collapse", when:"1990–91",
  q:"How does White (2001) describe the economic impact of Gorbachev's reforms?",
  pts:["“not only were shortages getting worse, so was quality”",
       "“The black market bloomed, enriching a criminal underground”",
       "Up to ¼ of the population living below the poverty line by 1990",
       "In 1990 national income fell; in 1991 the extreme fall of about 15% was greater in relative terms than the USA during the 1930s"] });
add("18.4 Impact of Perestroika and Glasnost", { id:"cw3-glasnost", exp:"Glasnost was meant to help the economy by allowing feedback, but by weakening CPSU authority it allowed ethnic grievances to come out, which Hosking says destroyed the USSR. Hobsbawn’s point is that glasnost removed authority while perestroika removed the old economy with nothing to replace either. It was hard to reverse and encouraged Eastern Europeans to reject communism, so its consequences were unintended.", title:"Glasnost and its unintended consequences", when:"from 1986",
  q:"What was glasnost, and what were its unintended consequences?",
  pts:["Openness, from 1986: aimed to overcome bureaucratic inertia and gather feedback to improve the economy — reduced CPSU power, enabled multicandidate elections, freer media",
       "Hosking (1993): “the whole dynamic of glasnost thrust ethnic factors to the centre of the stage… The result was to destroy the Soviet Union. He unleashed impulses, which proved much more powerful than he expected.”",
       "Hobsbawn (1999): glasnost “amounted to the destruction of authority”, perestroika “the destruction of the old mechanisms that made the economy work, without providing any alternative… an explosive combination”",
       "Once begun, hard to reverse without undermining Gorbachev's credibility or Western relations — made it harder to control Eastern Europe",
       "Gorbachev mistakenly believed Eastern Europeans would choose ‘reformed communism’ — they voted communism out entirely",
       "Verdict: exacerbated a pre-existing decline; eroded faith in Gorbachev, CPSU and the system — “highly regarded abroad but despised and ridiculed at home”"] });
add("18.5 Gorbachev's ‘New Thinking’ in Foreign Relations", { id:"newthinking", exp:"New Thinking was driven by need: costly competition was hurting the reforms at home, so Gorbachev redefined security as political and shared rather than military. Each principle undermines a Cold War assumption, from the arms race (confrontation brings matching responses) to the class approach (universal values). Declaring the USSR a ‘normal state’ removed the ideological basis for the Cold War itself.", title:"Gorbachev's ‘New Thinking’", when:"from 1985",
  q:"What were the aims and key principles of Gorbachev's ‘New Thinking’?",
  clue:"Soviet foreign-policy approach from 1985 replacing the ‘class approach’ with universal values; the USSR as a ‘normal state’.",
  pts:["Introduced to ease costly Cold War competition and support domestic reform, moving away from adversarial competition",
       "Superpower confrontation is counter-productive — gains stimulate matching responses",
       "Military power does not guarantee security; only political means and common solutions can",
       "One state's security must not come at another's expense; 3rd World conflict brought Moscow little tangible gain",
       "All states are interdependent; universal values (human rights, non-use of force, democracy) replace the ‘class approach’",
       "The USSR was a ‘normal state’, not seeking world hegemony"] });
add("18.5 Gorbachev's ‘New Thinking’ in Foreign Relations", { id:"cw3-nt-historians", exp:"These historians explain New Thinking through both necessity and conviction. Petersen links it to the burden of defence spending and the failure of military actions like Afghanistan; Brands stresses the belief that only major reform could save the USSR. Powaski adds the ideological break: rejecting inevitable conflict with capitalism made coexistence permanent. This supports the Soviet initiative school.", title:"Historians on the origins of New Thinking", when:"1970s–1985",
  q:"What do Petersen, Brands and Powaski say about why Gorbachev adopted New Thinking?",
  pts:["Petersen (1993): as the economy stagnated in the latter 1970s, defence spending reached 15-17% of GNP, prompting a decision to slow military spending",
       "Petersen: coincidental evidence of the ineffectiveness of military action (Afghanistan, deployment of SS20s, shooting of the Korean airliner)",
       "Brands (1993): Gorbachev was among those “deciding that only major reforms could prevent the SU from falling by the wayside.”",
       "Powaski (1997): Gorbachev rejected the Marxist-Leninist precept that conflict between communism and capitalism was historically inevitable — coexistence permanent, not an interlude"] });
add("18.5 Gorbachev's ‘New Thinking’ in Foreign Relations", { id:"cw3-nt-manifest", exp:"New Thinking was turned into concrete actions: détente, arms treaties, withdrawal from Afghanistan and Eastern Europe and rapprochement with China. The backlash matters because hardliners saw these steps as surrendering superpower status and buffer security, which explains the growing opposition that led to the August 1991 coup. So the policy that ended the Cold War also weakened Gorbachev at home.", title:"Manifestations of New Thinking and conservative backlash", when:"1985–89",
  q:"How was New Thinking manifested and what backlash did it provoke?",
  pts:["New détente with the West; reduced military expenditure; arms-control treaties (INF)",
       "Disengagement from the 3rd World (withdrawal from Afghanistan) and Eastern Europe",
       "Rapprochement with China (1989 — first Soviet visit since Khrushchev)",
       "Conservatives felt he compromised superpower status and buffer security, ‘kowtowing’ to Reagan/Deng",
       "Roberts (1994): “the loss of Eastern Europe, the reduction of Soviet military power… these were all objects of hard-line criticism, including within his own administration.”"] });
add("18.5 Gorbachev's ‘New Thinking’ in Foreign Relations", { id:"cw3-sinatra", exp:"The Sinatra Doctrine reversed the Brezhnev Doctrine: instead of using force to keep satellites communist, Gorbachev let them choose their own governments. Gorbachev’s own words show he believed force works only for a time. Its significance is that it removed the threat of Soviet intervention, which was the precondition for the 1989 revolutions, and, as Powaski says, convinced most Westerners he meant to end the Cold War.", title:"The Sinatra Doctrine", when:"1988–89",
  q:"What was the Sinatra Doctrine and how did it differ from the Brezhnev Doctrine?",
  clue:"Named after the singer of ‘My Way’: Eastern European states could choose their own governments, even non-communist ones.",
  pts:["Gorbachev allowed — even encouraged — Eastern European states to pick their own governments through elections, even if non-communist (‘My Way’ — Frank Sinatra)",
       "Response to the Prague Spring (1968); ended the Brezhnev Doctrine (which justified intervention in Hungary 1956 and Czechoslovakia 1968)",
       "Gaddis (2005), Gorbachev in Perestroika: “One could always suppress, compel, bribe, break or blast… but only for a certain period… Let everyone make his own choice, and let us all respect that choice.”",
       "Lundestad (2003): the Warsaw Pact's formal denunciation of the Brezhnev Doctrine (Dec 1989) confirmed a policy already pursued; no troops sent against large East German demonstrations",
       "Powaski: “The demise of the Brezhnev Doctrine persuaded all but the most hard-line Westerners of Gorbachev's determination to end the Cold War.”"] });
add("18.5 Gorbachev's ‘New Thinking’ in Foreign Relations", { id:"cw3-nt-actual", exp:"This card shows New Thinking was not just talk: the USSR cut aid to Third World allies, left Afghanistan, signed INF and made unilateral cuts. The unilateral element is key because it broke traditional suspicion and made Western reciprocity possible. Use it as evidence that the Soviet side took the most proactive steps to end the Cold War, supporting the Soviet initiative school.", title:"Actualisation of the Soviet shifts", when:"1985–88",
  q:"How were the shifts in Soviet foreign policy actualised?",
  pts:["Withdrawal from the 3rd World: scaled down/ended aid to Nicaragua, Cambodia, Angola, Ethiopia; pledged (1988) to extricate the USSR from Afghanistan; rapprochement with China",
       "Arms reduction: 4 Reagan–Gorbachev summits (1985–88), culminating in the INF Treaty (Dec 1987)",
       "Unilateral conventional cuts (Dec 1988): 500,000 troops, 10,000 tanks from Europe over 2 years, no reciprocity expected",
       "Lightbody: Gorbachev “had broken the traditional suspicion of Soviet intentions.”"] });
add("18.6 The August Coup and Takeover by Yeltsin", { id:"cw3-coup-context", exp:"Gorbachev was caught between two sides. Conservatives saw his reforms eroding CPSU control and the Union through demotions, elections and republic autonomy, while reformers thought he was too slow, slow to disclose Chernobyl and possibly heading towards dictatorship. This loss of support from both camps explains why he was so isolated by 1991 and why the coup and Yeltsin’s rise followed.", title:"Political context of the August Coup", when:"1986–91",
  q:"Why were both conservatives and reformers unhappy with Gorbachev before the August Coup?",
  pts:["Conservatives (military, ideologues, central planners) resented: demotions of hardliners for reformers; glasnost-elections eroding CPSU control",
       "Also: new Congress of People's Deputies/Executive President position; republic autonomy/Law of Secession",
       "Reformers unhappy with: Executive President position (feared as imminent dictatorship); Shevardnadze's resignation; half-hearted autonomy measures",
       "Also: delayed Chernobyl (1986) disclosure; Yeltsin's dismissal (1987) then comeback as elected President of Russia (1990)"] });
add("18.6 The August Coup and Takeover by Yeltsin", { id:"augustcoup", exp:"The coup was meant to stop the new Union Treaty from loosening the USSR, but it backfired. Yeltsin’s resistance made him the hero while Gorbachev looked weak, and Yeltsin then banned the CPSU and ended central control, so the republics could leave. Sturua’s view shows that the coup intended to save the old system actually ended both communism and perestroika.", title:"The August Coup", when:"19–21 Aug 1991",
  q:"What triggered the August Coup, how did it fail, and what was its impact?",
  clue:"Hardliners placed Gorbachev under house arrest in Crimea; Yeltsin stood on a tank outside the Russian White House.",
  pts:["Trigger: the new Union Treaty (turning the USSR into a looser confederation)",
       "Plotters incl. VP Yanayev, PM Pavlov, Defence Minister Yazov, KGB chief Kryuchkov; Gorbachev under house arrest in Crimea",
       "Yeltsin denounced the coup, stood on a tank outside the Russian White House; coup collapsed within 2 days",
       "Yeltsin then stripped Gorbachev of power, banned the CPSU, forced his resignation as CPSU chief, ending central control from Moscow",
       "Impact: Gorbachev looked weak; Yeltsin gained popularity and consolidated power; republics could break away unilaterally",
       "Sturua (1990): “The failed coup signalled not only the end of communism but the end of perestroika as well.”"] });
add("18.6 The August Coup and Takeover by Yeltsin", { id:"cw3-yeltsin-why", exp:"Yeltsin’s reasons were practical: holding the Union together risked bloodshed, many republics were a financial burden, and Russia, being richer and more advanced, would do better alone. This shows that the USSR’s end was partly a Russian choice, not only the result of breakaway republics, which matters when weighing Yeltsin’s role against Gorbachev’s in the collapse.", title:"Why Yeltsin let the USSR break up", when:"1991",
  q:"Why did Yeltsin let the USSR break up?",
  pts:["Understood that attempting to hold it together risked bloodshed",
       "Accepted many republics were an economic burden",
       "Calculated that wealthier/advanced Russia was better off going its own way"] });
add("18.7 Dissolution of the USSR and Resignation of Gorbachev", { id:"cw3-dissolution", exp:"The sequence shows how quickly the USSR unravelled after the coup. The three Slavic leaders created the CIS, most republics followed within two weeks, and Gorbachev resigned, leaving the USSR to cease to exist in law. Since this happened two years after Malta, it reinforces that the Cold War’s end and the USSR’s collapse are separate events.", title:"Dissolution of the USSR", when:"Dec 1991",
  q:"Outline the dissolution of the USSR in December 1991.",
  clue:"Byelorussian, Russian and Ukrainian leaders signed a declaration creating a Commonwealth open to all former Soviet republics.",
  pts:["7 Dec 1991: leaders of Byelorussian SSR, Russian SFSR and Ukrainian SSR sign the Minsk Declaration, dissolving the USSR and creating the CIS, open to all former Soviet republics",
       "By 20 Dec 1991: 11/15 republics had broken away",
       "25 Dec 1991: Gorbachev resigns (2nd resignation in 4 months) as Executive President of the USSR",
       "Yeltsin takes over the Kremlin office; the USSR ceases to exist in international law"] });
add("18.8 Concluding Thoughts — End of the Cold War vs. Collapse of the USSR", { id:"cw3-collapse-roles", exp:"No single actor caused the collapse. Gorbachev started reforms with consequences he did not foresee and would not use force to control; Yeltsin exploited the moment; the republics’ long-denied nationalism resurfaced; and the USA was largely absent, with Bush even trying to keep the USSR together. The break-up then made the Cold War’s end definitive, as there was no longer a USSR to contain.", title:"Roles in the USSR's collapse", when:"1985–91",
  q:"What roles did Gorbachev, Yeltsin, Reagan/USA and the Soviet republics play in the collapse of the USSR?",
  pts:["Break-up (Dec 1991) = definitive end of the Cold War: no USSR to contain, reorienting US policy toward diffuse threats (nationalism, religious fundamentalism)",
       "Gorbachev: well-intentioned reforms with unintended, unmanageable outcomes; did not anticipate consequences, unwilling to use coercion, eventually lost the ability to",
       "Yeltsin: seized the moment to end CPSU legitimacy and remove Russia from the Union, sealing its fate while securing his own future",
       "Reagan/USA: contributed to Soviet realisation that antagonism was unsustainable, but largely absent from the actual events; Bush cooperated (incl. a $1.1bn loan in 1991), aiming to preserve the USSR out of fear of disorder",
       "Soviet Republics: decades/centuries of denied national self-determination resurfaced once reforms failed and legitimacy crumbled"] });
add("18.8 Concluding Thoughts — End of the Cold War vs. Collapse of the USSR", { id:"cw3-garthoff", exp:"Garthoff rejects the triumphalist view, arguing that ‘victory’ came from Soviet leaders recognising their system’s failures, not from Western containment or Reagan’s build-up. Brown and Lévesque go further, crediting Gorbachev almost entirely and saying Reagan’s hard line slowed things. The irony noted is that Gorbachev wanted to end the Cold War in order to save the USSR, yet it collapsed anyway.", title:"Garthoff and the Gorbachev-credit view", when:"2003",
  q:"What do Garthoff, Archie Brown and Jacques Levesque argue about who won the Cold War, and how is the end of the Cold War related to the USSR's collapse?",
  pts:["Garthoff (in Lundestad, 2003): “The West did not, as is widely believed, win the Cold War through geopolitical containment and military deterrence. Still less… by the Reagan buildup and the Reagan Doctrine…”",
       "Garthoff: “‘victory’ came when a new generation of Soviet leaders realised how badly their system at home and their policies abroad had failed.”",
       "Archie Brown, Jacques Levesque: Gorbachev virtually all the credit; Reagan's hard-line anti-communism probably slowed the end — decisive was Gorbachev's ‘idealistic view of the world, based on universal reconciliation’",
       "End of the Cold War and USSR collapse: analogous/parallel processes with similar roots (Gorbachev, limits of communist rule, popular self-determination)",
       "End of the Cold War was desirable for Gorbachev; the USSR's collapse tragically was not — he hoped ending the Cold War would ensure the USSR's continuity"] });

/* ── 19. Eastern European Movements and Revolutions in the 1980s ── */
add("19. Eastern European Movements and Revolutions", { id:"cw3-movements-def", exp:"The definitions matter because most 1989 changes were popular movements, peaceful mass pressure, rather than violent revolutions, with Romania the exception. Gaddis’s use of Gorbachev’s own words is striking: even the Soviet leader credited ordinary people, whose actions created a collapse no one could stop and forced leaders to follow. This is the core claim of the People Power school.", title:"Popular movements vs. revolutions", when:"1989",
  q:"Define ‘popular movements’ and ‘revolutions’, and give Gaddis's view of who made 1989 happen.",
  pts:["Popular movements: power/pressure demonstrated by large numbers of the public in non-violent ways — populist driving force invoking grassroots opinion, usually opposing organised corporate/political forces",
       "Revolutions: the usually violent attempt by many people to end the rule of one government and start a new one",
       "Gaddis (2005), citing Gorbachev to Bush at Malta (1989): “ordinary people” made 1989 happen — Hungarians, Poles, East Germans",
       "They had “simple priorities… saw, seized, and sometimes stumbled into opportunities… caused a collapse no one could stop. Their ‘leaders’ had little choice but to follow.”"] });
add("19.1 Reasons for the Emergence of Popular Movements", { id:"cw3-movements-reasons", exp:"Three long-term grievances, denied national independence, oppressive rule and failed living standards, explain why discontent existed; earlier uprisings show communism had always been imposed from outside. But the trigger was opportunity: glasnost and elections gave movements space, and when Gorbachev did not crush them they grew bolder. This links People Power to Gorbachev’s choices.", title:"Reasons for Eastern European popular movements", when:"1980s",
  q:"Why did popular movements emerge in Eastern Europe in the 1980s?",
  pts:["Independence/self-determination denied since WWII — prior uprisings in East Germany (1953), Hungary (1956), Czechoslovakia (1968), Poland (1980) show communism always ‘imposed from without’ (Mason)",
       "Disgust/hatred of high-handed, oppressive rule denying freedom of thought/dissent — scale unexpected (despite glasnost); system had lost moral legitimacy by 1989",
       "Communism had not delivered promised living standards — stagnation, high foreign debt, low per-capita GDP vs expanding Western Europe (Solidarity began as a trade union for better wages/conditions)",
       "Movements exploited opportunities from glasnost and multi-party elections; when Gorbachev chose not to suppress them they grew emboldened and widespread, ending the physical symbols of the Cold War"] });
add("19.2 Timeline: The 1989 Movements", { id:"cw3-timeline-1989a", exp:"The sequence shows Soviet signals opening the door before the people walked through it. Gorbachev and Shevardnadze repeatedly said Moscow would not intervene, and Poland’s Round Table and elections followed, producing the first non-communist government. Hungary’s opened border was a crucial crack, as it later let East Germans escape. Note how quickly events moved once the threat of force was removed.", title:"1989 timeline: Dec 1988–Aug 1989", when:"Dec 1988–Aug 1989",
  q:"What happened in Eastern Europe between Dec 1988 and Aug 1989?",
  pts:["Dec 1988: Gorbachev tells the UN the Brezhnev Doctrine would not be enforced",
       "Feb 1989: Jaruzelski brings Solidarity to Round Table Talks; agrees to partly free elections in June",
       "Apr 1989: Gorbachev tells Eastern European leaders they must govern without Soviet support",
       "May 1989: Shevardnadze: “he could imagine no occasion in which Soviet troops might intervene in a Warsaw Pact country.”",
       "Jun 1989: Solidarity wins 99/100 Senate seats and all non-reserved lower-house seats; Hungary dismantles its barbed-wire fence with Austria",
       "Aug 1989: first non-communist postwar government in Eastern Europe takes power in Poland (Mazowiecki, PM)"] });
add("19.2 Timeline: The 1989 Movements", { id:"cw3-timeline-1989b", exp:"The second half of 1989 shows a chain reaction: the flood of East Germans through Hungary, the Wall breached, and communist regimes falling in Bulgaria and Czechoslovakia within weeks. Romania stands out as the violent exception, where Ceaușescu tried to shoot protesters and was executed. Use this card for the domino effect of 1989 and its mostly peaceful character.", title:"1989 timeline: Sep–Dec 1989", when:"Sep–Dec 1989",
  q:"What happened in Eastern Europe between Sep and Dec 1989?",
  pts:["Sep 1989: 130,000 East Germans have flooded into Hungary en route West",
       "Oct 1989: new non-communist Hungarian republic declared",
       "Nov 1989: 9th Berlin Wall breached; 10th Bulgaria's Zhivkov steps down; 17th Prague demonstrations begin — by year end Vaclav Havel is President",
       "Dec 1989: Poland restores its pre-war name/erases the CPSU's constitutional role",
       "17th–25th Dec: Ceaușescu orders troops to fire on protesters, is booed offstage, then arrested and executed with his wife"] });
add("19.3 Case Study: Poland", { id:"cw3-poland-economy", exp:"Poland’s economic collapse explains why it led the 1989 breakthroughs. Despite heavy investment and Western imports, growth turned negative, debts and deficits soared, and inflation, shortages and a black market followed. Combined with its tradition of rebellion noted by Lévesque, economic failure created strong pressure for change and showed communism failing to deliver its promises.", title:"Poland's economic crisis", when:"1970–1981",
  q:"Describe Poland's economic conditions before and during the rise of Solidarity.",
  pts:["Levesque (2010): Poland made the first breakthrough of 1989; always the most rebellious Warsaw Pact member (upheavals 1956, 1970, 1976, 1980-81); “for a year, the regime had teetered on the verge of complete collapse”",
       "National income growth: 9% (1970–75) → 6.8% (1976) → 5% (1977) → 3% (1978) → –2.3% (1979) → –5.4% (1980), despite Gierek-era capital accumulation and Western technology imports",
       "Trade deficits with the West: cumulative $303m (1961–70) → ≈$2.6bn/year (1975–78)",
       "By 1980 external debt $23bn (+$2bn short-term, +≈$2bn owed to the USSR/Eastern Europe)",
       "Open inflation returned (8.5% in 1980, >30% annualised by mid-1981); chronic shortages, rationing, thriving ‘grey’/black market (Nuti, 1981) → pressure for market reform"] });
add("19.3 Case Study: Poland", { id:"solidarity", exp:"Solidarity grew from economic grievance, strikes after huge food-price rises, into a mass movement of about 10 million. Its significance is that it was the first independent trade union in the communist world, a direct challenge to the party’s monopoly. Wałęsa’s acknowledgement of the party’s leading role shows the movement’s careful, peaceful tactics, which helped it survive.", title:"Rise of Solidarity", when:"Jul–Sep 1980",
  q:"How did Solidarity arise in Poland in 1980?",
  clue:"Gdańsk shipyard strikes produced the first independent trade union in the communist world, led by Lech Wałęsa.",
  pts:["Jul–Aug 1980: strikes involving 300,000 workers after ≈100% food-price rises",
       "31 Aug: the Gdańsk shipyard accepted the first independent trade union in the communist world, Solidarność, led by Lech Wałęsa",
       "Wałęsa in turn acknowledged the PUWP's leading role in state affairs",
       "Formally founded 22 Sep 1980; grew into a movement of ≈10 million (workers, intellectuals, students, farmers) using peaceful strikes/mass rallies"] });
add("19.3 Case Study: Poland", { id:"cw3-poland-martial", exp:"Martial law shows that before Gorbachev, the threat of Soviet force and domestic repression could still crush popular movements: Soviet manoeuvres and Jaruzelski’s crackdown banned Solidarity. Yet the regime lacked legitimacy and economic answers, so stalemate followed and new strikes in 1988 forced concessions. This shows People Power needed the changed Soviet context to succeed.", title:"Soviet/Polish responses: martial law to Round Table", when:"1980–Apr 1989",
  q:"How did the Soviet and Polish governments respond to Solidarity, 1980–89?",
  pts:["Soviet military manoeuvres on Poland's borders from Aug 1980; largest-ever Warsaw Pact exercises on the eve of Solidarity's Sep 1981 congress",
       "Martial law 12 Dec 1981 (Gen. Jaruzelski): thousands arrested, censorship/curfew; Solidarity banned (Oct 1982) — effectively crushed, though resistance relatively muted",
       "1982–88: political stalemate, deteriorating economy, no substantive reform (government lacked power and legitimacy)",
       "1988: new strikes demanded Solidarity's recognition; Apr 1989: government agrees to legalise it and allow free elections"] });
add("19.3 Case Study: Poland", { id:"cw3-poland-1989", exp:"Solidarity’s landslide made Poland the first Eastern European state with a non-communist leader. Its survival was unprecedented because earlier protests in 1956, 1968 and 1970 had been crushed, and that change in Soviet response encouraged others. The chain reaction of 1989 revolutions it set off ended Moscow-imposed regimes and contributed to the USSR’s later collapse.", title:"Solidarity's 1989 victory and impact", when:"Jun 1989–Dec 1990",
  q:"What happened in Poland's 1989 elections, and what was the impact on the Cold War and the USSR?",
  pts:["Jun 1989: Solidarity wins 99/100 new Senate seats and all 161 contestable Sejm seats",
       "Aug 1989: coalition with the PUWP; Mazowiecki first non-communist premier since the late 1940s; Dec 1990: Wałęsa elected President",
       "Survival unprecedented — a break from the hard line that bloodily ended the 1970 protests and the Soviet-led invasions of Hungary (1956) and Prague Spring (1968)",
       "Spread anti-communist ideals across the Eastern Bloc, weakening other communist governments",
       "June 1989 victory triggered a chain reaction of largely peaceful revolutions (‘Revolutions of 1989’), ending Moscow-imposed regimes and ultimately contributing to the USSR's 1991 dissolution"] });
add("19.4 Case Study: East Germany", { id:"cw3-gdr-economy", exp:"East Germany’s collapse came from rigidity: once the bloc’s most successful economy, it was failing by the late 1980s, and Honecker refused Gorbachev-style reforms while spending huge sums on subsidies. Mason’s point is that the GDR fell because it refused to reform, unlike Poland and Hungary, and as a state built only on socialism it lost its reason to exist once that failed.", title:"East Germany's economic conditions", when:"1980s",
  q:"What were East Germany's economic conditions in the 1980s?",
  pts:["Mason: GDR “was not so much a nation as a state built on an ideological concept—socialism”; fell “not after a period of reform, but because it refused to reform”; once Hungary opened its border (May 1989) refugees could not be stopped",
       "Haftendorn (2011): in the early 1980s the most successful socialist economy in Eastern Europe — though GNP and productivity just 60% of West Germany's — it approached collapse; legitimacy crumbled",
       "Late 1980s growth <1% p.a.; run-down infrastructure, labour/raw-material shortages; exports to the USSR increasingly rejected for poor quality from 1986",
       "Honecker rejected Gorbachev-style market reforms as contradicting Marxist ideology, spending over a fifth of government income subsidising housing/food/basic goods"] });
add("19.4 Case Study: East Germany", { id:"cw3-gdr-reunify", exp:"The division of Germany was the clearest physical form of the Cold War, with the Wall becoming the accepted status quo. Détente-era trade and exchange between the two Germanies revived national feeling, keeping the hope of reunification alive. Kohl’s insistence on staying in the Western camp shows why reunification later raised Cold War questions about where a united Germany would belong.", title:"Aspirations for German reunification", when:"1945–1984",
  q:"How did aspirations for German reunification develop?",
  pts:["Post-1945 division into FRG (West) and GDR (East, 1949), integrated into opposing blocs (NATO/EC vs Warsaw Pact/Comecon)",
       "Berlin Wall (built 1961) prevented East–West flight and became the accepted status quo",
       "1980s détente-era trade/cultural exchange (West Germany the USSR/Eastern Europe's largest Western trading partner) revived national sentiment on both sides",
       "Chancellor Kohl (1984) acknowledged the aspiration to unity while insisting Germany remain in the Atlantic camp"] });
add("19.4 Case Study: East Germany", { id:"cw3-leipzig", exp:"The Leipzig protests show how People Power grew: the church offered a safe space, and peaceful protest spread by word of mouth and Western TV. The turning point was 9 October, when local leaders faced a crowd far larger than the forces prepared and withdrew rather than risk a massacre. Rapidly growing numbers then forced Honecker out, showing the regime had lost the will to use force.", title:"Leipzig church-based peace movement", when:"1982–Oct 1989",
  q:"How did the Protestant-church peace movement and the Leipzig protests escalate in autumn 1989?",
  clue:"Pastor Christian Führer's weekly Friedensgebet at St. Nicholas grew into mass demonstrations chanting “Wir sind das Volk!”",
  pts:["Pastor Christian Führer's weekly Friedensgebet at Leipzig's St. Nicholas Church (from 1982) gave a safe meeting space; demonstrations began 4 Sep 1989, spread to Karl Marx Square, then other cities (via West German TV/word of mouth)",
       "Bierbach (2019): 70,000–100,000 protest in central Leipzig; leadership does not order security forces to act; candles, chants ‘We are the people,’ ‘Freedom and free elections’, ‘No violence’",
       "Oct 7 (40th-anniversary protests): forceful state response, ≈3,500 arrests",
       "Oct 9, Leipzig: >70,000 protesters (state prepared 8,000 police/military) chant “Wir sind das Volk!”; local leaders, lacking orders, withdrew rather than risk a massacre",
       "Oct 16: 120,000 demonstrators (Honecker forced to resign 2 days later); Oct 23: >320,000"] });
add("19.4 Case Study: East Germany", { id:"berlinwall", exp:"The Wall fell partly by accident, through Schabowski’s mistaken announcement, but it was the crowds who turned that mistake into the opening of the border. Its significance is symbolic and political: the Wall represented the division at the heart of the Cold War, so removing it settled one of the conflict’s oldest disputes and directly enabled Bush and Gorbachev’s declaration at Malta.", title:"Fall of the Berlin Wall", when:"9 Nov 1989",
  q:"How did the Berlin Wall fall, and what was its significance for the Cold War?",
  clue:"Spokesman Günter Schabowski mistakenly announced immediate free travel to the West at a press conference.",
  pts:["9 Nov 1989: Günter Schabowski mistakenly announces immediate free travel to the West at a press conference",
       "East Germans flood the border, passport checks abandoned, the Wall opened — over 2 million East Berliners cross that weekend (‘wall woodpeckers’ dismantle sections by hand)",
       "Germany formally reunited 3 Oct 1990, 11 months after the Wall fell",
       "Iron Curtain/Wall symbolised the core divisions of the Cold War (political-economic systems, visions for postwar Europe, militarised blocs) — tensions persisted while they stood, despite Reagan–Gorbachev relations",
       "The 1989 revolutions removed the Iron Curtain, resolving one of the Cold War's original and most lasting disagreements — directly enabling the Malta declaration (Dec 1989)"] });
add("19.5 Concluding Thoughts", { id:"cw3-peoplepower-limits", exp:"People Power was decisive on the ground but depended on Gorbachev’s refusal to use force; once the Brezhnev Doctrine was dropped, the floodgates opened. McCauley adds that Gorbachev expected reformed socialism, yet he still did not intervene when he saw his mistake. The US contributed mainly through restraint, so the best argument links popular pressure to superpower choices.", title:"People Power and Gorbachev's role", when:"1985–89",
  q:"Why is ‘People Power’ alone an insufficient explanation of 1989?",
  pts:["Gorbachev's public repudiation of the Brezhnev Doctrine (from 1985, restated Apr 1989) removed the key lever of repression; when the Red Army did not crush Solidarity again, the ‘floodgates opened’",
       "McCauley: Gorbachev assumed Eastern Europeans had “chosen socialism and would never go back on this”; reform would enhance socialism's appeal, not end it",
       "Even once he realised he had allowed ‘too much’, he chose not to reimpose Soviet force",
       "US role limited but not absent: decades of funding Radio Free Europe/Radio Liberty, covert Solidarity funding, rhetorical support (e.g. Havel's Charter 77)",
       "For Feb–Nov 1989, “the United States' contribution lay mainly in what it did not do.”"] });
add("19.5 Concluding Thoughts", { id:"cw3-jarausch", exp:"Jarausch stresses that unarmed people defeated a state with huge repressive power through nonviolent resistance, which is why he calls 1989 magical and miraculous. His exception for Romania underlines how unusual the peaceful pattern was. Use this quotation to support the People Power school, while remembering that the regime’s restraint also depended on Moscow not intervening.", title:"Jarausch on the ‘magical’ fall of the Wall", when:"2009",
  q:"How does Jarausch (2009) characterise the fall of the Berlin Wall?",
  pts:["“magical because it signaled the peaceful triumph of people's power over a regime that commanded enormous repressive force”",
       "“it was nonviolent civil resistance that brought down the ugly concrete barrier”",
       "“That the rebels—save for those in Romania—remained peaceful… all this still seems quite miraculous.”"] });

/* ── 20. Historical Interpretations of the End of the Cold War — Three Schools ── */
add("20. Historical Interpretations — Three Schools", { id:"historiography3", exp:"The three schools each place the decisive cause in a different actor: the USA, the USSR’s leadership or the people. The quotations show their emphasis: Bacevich captures triumphalist confidence that the USA now shaped history, Zubok’s ‘inadvertent liberator’ credits Gorbachev, and Gaddis’s sandpile image stresses ordinary people. Strong answers weigh these together, since each school depends on the others.", title:"Three schools on the end of the Cold War", when:"historiography",
  q:"What were the different interpretations of the end of the Cold War — and who/what was responsible?", qs:"notes",
  pts:["Western Triumphalist School: Reagan/US containment strategy ‘broke the back’ of the Soviet empire",
       "Soviet Initiative School: Gorbachev was the key player; Reagan largely reactive",
       "‘People Power’ School: popular pressure across Europe leading to the 1989 revolutions was most important",
       "Bacevich (2009), triumphalist thinking: the Soviet unraveling brought history to a definitive turning point; up to the US to determine what came next — “there had previously been two superpowers; now only one remained.”",
       "Zubok (2022): “‘The Soviet factor’… proved to be a crucial factor in the success of the peaceful revolutions… there might be a place for Gorbachev, the inadvertent liberator.”",
       "Gaddis (2005): the USSR, its empire, its ideology – and therefore the Cold War – was “a sandpile ready to slide”; those who dropped the grains were “ordinary people with simple priorities.”"] });
add("20. Historical Interpretations — Three Schools", { id:"cw3-triumphalist", exp:"The triumphalist school emerged from American confidence after Soviet collapse, which helps explain its focus on US strategy. Its logic is that containment plus Reagan’s build-up exploited Soviet weaknesses until the empire broke, supported by spending figures. But its limits are serious: little sign of Soviet bending before 1985, it mixes long-term Soviet weaknesses with US effects, and it ignores Gorbachev and the people.", title:"Western Triumphalist School", when:"post-1991",
  q:"Outline the Western Triumphalist School: context, key authors, arguments, evidence and limitations.",
  pts:["Context: for many American authors the USSR's collapse marked the West's ‘victory’; USA the remaining superpower (Fukuyama's ‘unipolar moment’/Krauthammer)",
       "Authors: Robert Gates; Bush, Scowcroft & Hutchings; Fukuyama (The End of History…, 1992); Jay Winik (On the Brink, 1996); Beth A. Fisher (The Reagan Reversal, 2002); Gaddis (The Cold War: A New History, 2006); Jack Matlock (Reagan and Gorbachev, 2005)",
       "Argument: ‘triumph of the strategy of containment’ (Kennan, 1946) — “denied new conquests, the inherent weaknesses of Soviet communism ultimately would bring it down” (Gates); secret Reagan policies (1981–87) ‘broke the back’ of the Soviet empire",
       "Reagan inherited a USSR that had surpassed the US in the arms race; his build-up exacerbated Soviet financial vulnerability",
       "Evidence: US defence $134bn→$253bn (1980–89); ≈22%→27% of Soviet GDP to defence; Mujahedeen (US $1bn/yr vs Soviet ≈$8bn/yr); SDI; reduced technology/grain flows and lower oil prices",
       "Limitations: little evidence of Soviet ‘bending’ before 1985 (Afghanistan, arms race, KAL shoot-down = panic); conflates pre-existing weaknesses with US policy; ignores Gorbachev's and the people's agency"] });
add("20. Historical Interpretations — Three Schools", { id:"cw3-soviet-initiative", exp:"This school drew on Soviet archives and interviews, which revealed Gorbachev’s initiatives and Reagan’s reactive role. Its argument is that New Thinking and his personality, not US pressure, transformed Soviet policy and ended the European empire. Its limitations are that arms deals still needed US cooperation and that it may over-credit Gorbachev’s idealism when the system was already failing.", title:"Soviet Initiative School", when:"post-1991",
  q:"Outline the Soviet Initiative School: context, key authors, arguments, evidence and limitations.",
  pts:["Context: emerged after the opening of Soviet archives, declassified US documents, and interviews with former officials",
       "Authors: Jacques Lévesque (The Enigma of 1989, 1997); Frances Fitzgerald (Way Out There in the Blue, 2001); Raymond Garthoff (The Great Transition, 1994); William Pemberton (Exit with Honor, 1998); David Abshire (Saving the Reagan Presidency, 2005)",
       "Argument: Gorbachev the key player for both Reagan and Bush administrations; Reagan reactive. Pemberton: despite ‘evil empire’ rhetoric Reagan “joined Mikhail Gorbachev to bring the cold war to an end”; Reagan Victory lens downplays domestic Soviet factors",
       "Lévesque: New Thinking and Gorbachev's personality replaced the faded Stalinist imperial consensus with a neo-Leninist utopia based on consensus/pluralism, driving the quick disappearance of the Soviet European empire in 1989",
       "Evidence: rejection of the Brezhnev Doctrine (UN, Dec 1988); Sinatra Doctrine and non-intervention 1989; INF and unilateral cuts (1988); Gorbachev's Malta account crediting ‘ordinary people’",
       "Limitations: understates the ‘Reagan factor’ in sustaining diplomacy; risks over-crediting Gorbachev's ‘idealism’ while underplaying how badly the system had already failed"] });
add("20. Historical Interpretations — Three Schools", { id:"cw3-peoplepower", exp:"The People Power school shifts attention from leaders to ordinary citizens, arguing that dictatorships had to be pushed by mass protests and that a transnational grassroots movement revived civil society. Bartel’s line suggests 1989 was when people’s power peaked. Its limitation is that the movements succeeded only because Gorbachev chose not to use force and the US held back, so they operated within superpower choices.", title:"‘People Power’ School", when:"post-1989",
  q:"Outline the ‘People Power’ School: context, key authors, arguments, evidence and limitations.",
  pts:["Context: emerged after the fall of the Wall and the USSR's collapse, as new research interest in ordinary citizens",
       "Authors: Fritz Bartel (The Triumph of Broken Promises, 2022); Matthew Evangelista (Unarmed Forces, 1999)",
       "Argument: popular pressure leading to the 1989 revolutions most important; Bartel: the end “was the moment in which the people's power peaked and the moment in which it was overcome.”",
       "Transnational grassroots movement of Polish workers, Hungarian activists, German refugees and Czech dissidents; dictatorships had to be pushed by mass demonstrations into free elections",
       "Evidence: 1989 timeline (Solidarity's sweep, Leipzig's Monday demonstrations, Wall's fall); Gaddis's ‘sandpile’; Jarausch's ‘magical’ revolutions",
       "Limitations: understates Gorbachev's New Thinking/Sinatra Doctrine as precondition; US contribution was restraint — people power operated within, not independently of, superpower choices"] });

/* ── 21. Concluding Evaluation — Topic 3 Synthesis ── */
add("21. Concluding Evaluation — Topic 3 Synthesis", { id:"cw3-synthesis", exp:"The synthesis argues the three actors were connected, not competing: US pressure worked on existing Soviet weaknesses, Gorbachev turned those into policy changes, and those changes gave popular movements room to act. Each factor has a limitation that another fills. This action-reaction chain is the strongest framework for an essay, while keeping the 1989 versus 1991 distinction in mind.", title:"Synthesising responsibility for the end of the Cold War", when:"1981–91",
  q:"How should responsibility for the end of the Cold War be synthesised across the USA, the USSR and the people?",
  pts:["USA/Reagan: renewed containment strained the Soviet economy and helped persuade the USSR confrontation was fruitless — but causal link contested; 2nd-term role substantially reactive, partly restraint",
       "USSR/Gorbachev: New Thinking, Sinatra Doctrine, unilateral cuts, disengagement were the most proactive, sustained drivers — rooted in long-term decline and his reform agenda, though they unintentionally accelerated collapse",
       "The People: Solidarity, Leipzig, Wall-opening gave decisive on-the-ground pressure ending communist rule in 1989 — only possible because Gorbachev removed the Brezhnev Doctrine's threat",
       "None operates independently — an ‘action-reaction’, mutually-reinforcing dynamic (as with Topic 1) best explains the end",
       "US pressure → pre-existing Soviet weaknesses → Gorbachev's agency → concrete policy shifts → political space for popular movements",
       "Recall: end of the Cold War (1989) and USSR collapse (1991) related but not synonymous"] });
add("21. Concluding Evaluation — Topic 3 Synthesis", { id:"cw3-essay-soviet", exp:"To answer this, weigh Soviet initiative, which the notes call the most proactive and sustained driver, against American contributions: containment strained the USSR and Reagan sustained diplomacy. A strong judgement would agree largely but not wholly, since Soviet steps needed a willing US partner and 1989 was finally pushed through by the people, reflecting an action-reaction dynamic.", title:"Essay: Soviet, not American, achievement?", when:"discussion prompt",
  q:"‘The end of the Cold War was primarily a Soviet, not an American, achievement.’ How far do you agree?", qs:"notes",
  pts:["For: New Thinking, Sinatra Doctrine, unilateral cuts and disengagement were the most proactive, sustained drivers",
       "For: Reagan's 2nd-term role was substantially reactive (Schweitzer: “Reagan happened to be there when Gorbachev ended the Cold War”)",
       "Against: renewed containment strained the Soviet economy; Reagan crucial in sustaining diplomacy; arms-control treaties required active US negotiation",
       "Also: the People provided decisive pressure in 1989; action-reaction dynamic best explains the end"] });
add("21. Concluding Evaluation — Topic 3 Synthesis", { id:"cw3-essay-gorb-collapse", exp:"The question asks you to balance Gorbachev’s agency against deeper causes. His reforms unleashed forces he could not control and he refused to use coercion, which made him central. But structural problems predated him, Yeltsin seized the chance after the coup, and the republics’ nationalism resurfaced. A balanced answer sees Gorbachev as the trigger of a collapse rooted in long-term weaknesses.", title:"Essay: Gorbachev and the unintended collapse", when:"discussion prompt",
  q:"How far was Gorbachev responsible for the collapse of the USSR he did not intend?", qs:"notes",
  pts:["Gorbachev: well-intentioned reforms (perestroika/glasnost) with unintended, unmanageable outcomes; unwilling then unable to use coercion",
       "But long-term causes predated him: structure of the USSR, planned-economy inefficiencies, weak past leaders, social divide, cost of empire",
       "Yeltsin seized the moment after the August Coup to end CPSU legitimacy and remove Russia from the Union",
       "Republics' denied self-determination resurfaced; USA largely absent (Bush sought to preserve the USSR)"] });
add("21. Concluding Evaluation — Topic 3 Synthesis", { id:"cw3-essay-topdown", exp:"Top-down leadership produced the treaties and cuts that eased superpower tensions, while bottom-up pressure removed the physical symbols of division and made Malta possible. The key link is that the people could act only because Gorbachev removed the Brezhnev Doctrine and the USA stayed out. The best judgement is that the end required both, with leadership creating space that the people then used decisively.", title:"Essay: top-down vs bottom-up", when:"discussion prompt",
  q:"Assess the relative importance of top-down leadership (Reagan/Gorbachev) versus bottom-up popular pressure in ending the Cold War.", qs:"notes",
  pts:["Top-down: Reagan–Gorbachev convergence — summits, INF/CFE/START I, unilateral cuts",
       "Bottom-up: Solidarity, Leipzig demonstrations, fall of the Wall ended the physical symbols of division, enabling Malta (Dec 1989)",
       "Popular movements only possible because Gorbachev removed the Brezhnev Doctrine; US contribution “mainly in what it did not do”",
       "End of the Cold War = combination of top-down change and bottom-up pressure"] });
add("21. Concluding Evaluation — Topic 3 Synthesis", { id:"cw3-essay-sameprocess", exp:"The answer should largely disagree but acknowledge the connections. The end came first (1989) and did not need the collapse (1991), which was more a result than a cause, and Gorbachev wanted one but not the other. Yet they were parallel processes with shared roots, and the collapse made the Cold War’s end final by removing the USSR the USA had been containing.", title:"Essay: one and the same process?", when:"discussion prompt",
  q:"‘The end of the Cold War and the collapse of the Soviet Union were one and the same process.’ Do you agree?", qs:"notes",
  pts:["Disagree: end of the Cold War (1989, Malta) preceded the collapse (Dec 1991) and did not require it",
       "Collapse largely a product/outcome of the end of the Cold War, not its cause",
       "Parallel processes with similar roots: Gorbachev, the limits of communist rule, popular self-determination",
       "Collapse produced the definitive end — the USA no longer had a USSR to contain",
       "End of the Cold War desirable for Gorbachev; collapse was not"] });

/* ── 22. Quick-Revision Checklist — Topic 3 ── */
add("22. Quick-Revision Checklist — Topic 3", { id:"cw3-checklist", exp:"The checklist mirrors the four syllabus sub-topics plus historiography, so use it to test whether you can explain each actor’s role and evaluate it with evidence and historian quotations. Notice the repeated emphasis on evaluating limitations and comparing schools, which signals that exam questions reward judgement on relative importance rather than narrative alone.", title:"Topic 3 revision checklist", when:"revision",
  q:"What should you be able to do for Topic 3, according to the quick-revision checklist?",
  pts:["Explain ‘end of the Cold War’ vs ‘renewed containment’, placed in the periodisation (2nd Cold War 1979–85; New Détente 1985–91); 3 reasons for renewed containment with historian quotes",
       "Explain military containment, SDI, the Reagan Doctrine with at least 3 country cases; evaluate the Reagan Victory School and its limitations (incl. Korean Airlines incident)",
       "Explain the post-1985 shift (re-election, Able Archer 83, Shultz/rapport) and key summits/treaties (INF 1987, CFE 1989, START I 1991)",
       "Explain long-term Soviet decline; evaluate perestroika/glasnost (White, Hosking, Hobsbawn); New Thinking; Sinatra vs Brezhnev Doctrine; August 1991 coup and dissolution timeline",
       "Define popular movements vs revolutions; narrate Poland and East Germany case studies and their significance",
       "Compare all three historiographical schools: context, authors, arguments, evidence, limitations"] });

/* ── 23.1 Past-Year SBCS Questions ── */
add("23.1 Past-Year SBCS Questions", { id:"cw3-sbcs-2025a", exp:"For a compare-and-contrast question on Gorbachev’s views, the notes on perestroika and glasnost give context for judging what he believed and why. His words about respecting others’ choices show his reformist ideals, while his remark that SDI aimed to wear the USSR out shows awareness of Soviet strain. Comparing such views means looking at chronology and the situation when each source was produced.", title:"2025 SBCS (a): Gorbachev's views", when:"2025 A-Level",
  q:"Compare and contrast Sources A and B on Gorbachev's views on the situation in the Soviet Union. (2025 SBCS (a))", qs:"notes",
  pts:["Relevant content: perestroika and glasnost and their impact (White, Hosking, Hobsbawn)",
       "Gorbachev in Perestroika: “Let everyone make his own choice, and let us all respect that choice.”",
       "Gorbachev on SDI: “they're pursuing this program to wear us out.”",
       "Revision strategy: chronology, cause and effect; significance; change and continuity"] });
add("23.1 Past-Year SBCS Questions", { id:"cw3-sbcs-2025b", exp:"This assertion can be supported because planned-economy failures, a widening technology gap and heavy defence spending pushed Gorbachev to New Thinking. But it must be qualified: problems existed since the 1960s while policy stayed confrontational until 1985, so the immediate triggers were Gorbachev, Reagan’s softer second term and nuclear fear. US pressure and People Power also need weighing.", title:"2025 SBCS (b): Soviet economic problems", when:"2025 A-Level",
  q:"How far do Sources A–F support the assertion that Soviet economic problems were the reason for the end of the Cold War? (2025 SBCS (b))", qs:"notes",
  pts:["Support: planned-economy inefficiencies; output gap widened in the 1980s; defence 15–17% of GNP; New Thinking introduced to ease costly competition and support domestic reform",
       "Qualify: economic problems pre-dated 1985 (since the 1960s) yet policy stayed confrontational until Gorbachev — decline alone did not cause a timely shift",
       "Immediate triggers: Gorbachev's ascension (1985), Reagan's more conciliatory 2nd term, fear of nuclear war from the INF race",
       "Other factors: US pressure (Reagan Victory School), people power in 1989"] });
add("23.1 Past-Year SBCS Questions", { id:"cw3-sbcs-past", exp:"The past topics show examiners return to the turn from détente to confrontation, the 1989 collapse in Eastern Europe and the Soviet economy. The revision strategy recommends knowing chronology and cause and effect first, then significance, so you can handle Part (b) questions that ask about relative responsibility or whether a factor was decisive. Prepare a judgement for each actor.", title:"Earlier Topic 3 SBCS topics and strategy", when:"2019 / 2022",
  q:"Which past-year SBCS topics (2019–2025) relate to Topic 3, and what does the revision strategy recommend?",
  pts:["2019: End of Détente and Return to Confrontation",
       "2022: The Collapse of Communism in Eastern Europe",
       "2025: Gorbachev's views on the Soviet Union; Soviet economic problems as the reason for the end of the Cold War",
       "Strategy: (1) understand key events (chronology, cause and effect); (2) significance (significance, diversity); (3) assess outcomes (change and continuity)",
       "Common Part (b) types: how far a Cold War conflict (vs local factors)? relative superpower responsibility? who ‘won’?"] });

/* ── 23.4 Topic 3 Supplement — Players × Time-Period Matrix ── */
add("23.4 Players × Time-Period Matrix", { id:"cw3-matrix-usa", exp:"The matrix shows the US role changing by phase: first-term pressure, second-term cooperation, then Bush’s continuation through summits and treaties. Each claim has a counter-point, since the first view ignores Soviet and Eastern European agency and the second overlooks Reagan’s early hesitations. This helps you write phase-by-phase judgements rather than one blanket claim about the USA.", title:"Matrix: role of the USA 1981–91", when:"1981–91",
  q:"What was the USA's role in each sub-phase (1981–84, 1985–89, 1989–91)?",
  pts:["1981–84: containment strained Soviet resources, arguably forcing Gorbachev to end the Cold War from 1985 — but ignores the USSR itself and Eastern European people power",
       "1985–89: Reagan cooperated with Gorbachev (pre-empting nuclear war, reducing economic strain) — but ignores Reagan's own obstacles in the first 3 years after 1985 (wait-and-see, INF conditions in 1987)",
       "1989–91: Bush continued Reagan's work — annual summits, the CFE and START I treaties"] });
add("23.4 Players × Time-Period Matrix", { id:"cw3-matrix-ussr-ee", exp:"The matrix shows a shift in Soviet motives: pre-Gorbachev leaders kept up costly counter-containment, Gorbachev ended the Cold War to save resources, avoid nuclear war and gain aid, and after 1989 domestic crisis made ending it urgent. Eastern Europe moved from being a burden on the USSR to an active force using glasnost to leave Soviet control. This links economic strain to agency.", title:"Matrix: USSR and Eastern Europe 1981–91", when:"1981–91",
  q:"What were the roles of the USSR and Eastern Europe in each sub-phase?",
  pts:["USSR 1981–84: leaders before Gorbachev continued to counter-contain the USA, straining Soviet resources further",
       "USSR 1985–89: Gorbachev actively ended the Cold War to redirect resources to the economy, pre-empt nuclear war, secure US/IMF aid/trade — treaties, summits, withdrawal from Eastern Europe/3rd World, rapprochement with China",
       "USSR 1989–91: intensifying domestic problems increased the need to end the Cold War entirely",
       "Eastern Europe 1981–84: strained by Soviet economic aid obligations and resources used to suppress unrest",
       "Eastern Europe 1989–91: used glasnost/elections to vote in non-communist parties — Velvet Revolutions, Sinatra Doctrine, fall of the Wall/German unification followed"] });
add("23.4 Players × Time-Period Matrix", { id:"cw3-matrix-analysis", exp:"Gorbachev should not get full credit because his reforms had uncontrollable effects, he needed a willing US partner, and his policy cannot explain why Eastern Bloc regimes collapsed so completely. That last gap is filled by the people, whose role was largely independent. But both superpowers created the conditions, Gorbachev by allowing change and the USA by not intervening.", title:"Analysis: Gorbachev's actions and popular movements", when:"1985–91",
  q:"Why should Gorbachev not be given full credit, and how independent were the popular movements?",
  pts:["Gorbachev's solutions (New Thinking, glasnost, perestroika, Eastern European self-determination) eased US relations but unleashed unintended, uncontrollable domestic consequences",
       "Full credit doesn't explain why Eastern Bloc regimes couldn't persist (popular movements); a willing US partner (Reagan) was needed; end of Cold War (1989) preceded and is distinct from the collapse (1991)",
       "The People played an important, largely independent role in tearing apart the Iron Curtain — neither superpower directly orchestrated it",
       "Both superpowers created favourable conditions: Gorbachev allowed the revolutions (even without intending them); US non-intervention let them unfold organically"] });
add("23.4 Players × Time-Period Matrix", { id:"cw3-two-coups", exp:"The phrase captures the irony of August 1991. The conservatives’ coup failed because of Yeltsin, public resistance shaped by glasnost and the plotters’ own weaknesses. Yeltsin’s ‘second coup’ then took power from Gorbachev, banned the CPSU and ended central control, which let the republics break away. So the coup meant to preserve the USSR ended up destroying it.", title:"The August Coup as ‘two coups in one’", when:"Aug–Dec 1991",
  q:"Why is the 1991 August Coup described as ‘two coups in one’?",
  pts:["1st coup (conservatives): placed Gorbachev under house arrest on holiday in Crimea — culmination of conservative opposition to reform",
       "Failed due to Yeltsin's intervention, long-term effects of glasnost (public responded against the coup), and the plotters' own limitations",
       "2nd coup (reformers, esp. Yeltsin): ‘saved’ Gorbachev but took over his powers — stood on a tank outside the Russian White House",
       "Banned the CPSU (implicated in the coup), forced Gorbachev's resignation as CPSU General Secretary, ending central control from Moscow",
       "Triggered republics' breakaway: 7 Dec 1991 CIS replaced the USSR; Gorbachev resigned as Executive President 25 Dec 1991"] });
add("23.4 Players × Time-Period Matrix", { id:"cw3-link-summary", exp:"Gorbachev hoped ending the Cold War would free resources from rivalry with the USA, China and the Third World to revive the economy, as normalisation with China showed. But perestroika failed to deliver results in time, so ending the Cold War could not save the USSR. The summary lists the joint achievements of Reagan and Gorbachev, showing the end came through shared diplomacy plus Soviet disengagement.", title:"Link between Soviet collapse and the end of the Cold War", when:"1985–91",
  q:"How were the Soviet collapse and the end of the Cold War linked, and how did Gorbachev and Reagan together end the Cold War?",
  pts:["Ending the Cold War let resources be diverted from the arms race/PRC rivalry/Eastern Europe/3rd World to the stagnated economy; PRC normalisation brought new economic opportunities and US/IMF aid",
       "Ultimately undermined by perestroika's failure to deliver results in time",
       "How they ended it: reduced focus on military competition and ideology; new détente — arms-control treaties, esp. INF, CFE, START I",
       "Normalisation of relations with the PRC; withdrawal from the 3rd World — Africa, Latin America, Asia, the Middle East",
       "Disengagement from Eastern Europe — the 1989 Sinatra Doctrine"] });
})();
